bool launch_windows_path(const ::cw::lib::String& executable, const ::cw::lib::String& target,
                          bool arg_select_file) {
    // ShellExecute は、起動元の Job Object
    // の外にある既存の Explorer やアプリへ処理を委
    // ねる場合がある。 そのプロセスが使用中でも保管庫が確定・
    // 削除し得るため、一時的なセッションパスは安全に渡せない。
    if (managed_userdata_session()) return false;
    const auto native_target = std::filesystem::u8path(target).native();
    std::wstring parameters;
    if (arg_select_file) {
        // Explorerの/select引数は引用符内のパスを受け取る。
        parameters = L"/select,\"" + native_target + L"\"";
        const auto result = ::ShellExecuteW(nullptr, L"open", L"explorer.exe", parameters.c_str(),
                                            nullptr, SW_SHOWNORMAL);
        return reinterpret_cast<INT_PTR>(result) > 32;
    }
    try {
        if (!executable.empty()) {
            ::cw::lib::ProcessOptions options;
            options.executable = executable;
            options.arguments = {target};
            ::cw::lib::ExternalProcess::start_detached(options);
        } else {
            ::cw::lib::ExternalProcess::open_file(target);
        }
        return true;
    } catch (...) { return false; }
}
