bool scenario_value_tuple_less(const std::vector<::cw::lib::Value>& left,
                               const std::vector<::cw::lib::Value>& right)
{
    const auto count = (std::min)(left.size(), right.size());
    for (std::size_t index = 0; index < count; ++index) {
        const auto comparison = ::cw::util::cmp(std::optional<::cw::lib::Value>(left[index]),
                                                std::optional<::cw::lib::Value>(right[index]));
        if (comparison != 0) return comparison < 0;
    }
    return left.size() < right.size();
}

bool scenario_header_less(const std::shared_ptr<::cw::header::ScenarioHeader>& left,
                          const std::shared_ptr<::cw::header::ScenarioHeader>& right,
                          ::cw::lib::Integer sort_type)
{
    if (!left || !right) return static_cast<bool>(right);
    const auto name_left = value_string(left->m_name);
    const auto name_right = value_string(right->m_name);
    const auto author_left = value_string(left->m_author);
    const auto author_right = value_string(right->m_author);
    switch (sort_type) {
    case 0:
        // Python と同様、既定の選択ではデータベースの対象レベル順を維持する。
        return false;
    case 2:
        return scenario_value_tuple_less(
            {::cw::lib::Value(author_left), left->m_levelmin, left->m_levelmax,
             ::cw::lib::Value(name_left), ::cw::lib::Value(left->m_fname), left->get_mtime_reversed()},
            {::cw::lib::Value(author_right), right->m_levelmin, right->m_levelmax,
             ::cw::lib::Value(name_right), ::cw::lib::Value(right->m_fname), right->get_mtime_reversed()});
    case 3:
        return ::cw::util::sort_by_filename_cmp_fname(left->m_fname, right->m_fname) < 0;
    case 4:
        return scenario_value_tuple_less(
            {left->get_mtime_reversed(), left->m_levelmin, left->m_levelmax,
             ::cw::lib::Value(name_left), ::cw::lib::Value(author_left), ::cw::lib::Value(left->m_fname)},
            {right->get_mtime_reversed(), right->m_levelmin, right->m_levelmax,
             ::cw::lib::Value(name_right), ::cw::lib::Value(author_right), ::cw::lib::Value(right->m_fname)});
    default:
        return scenario_value_tuple_less(
            {::cw::lib::Value(name_left), left->m_levelmin, left->m_levelmax,
             ::cw::lib::Value(author_left), ::cw::lib::Value(left->m_fname), left->get_mtime_reversed()},
            {::cw::lib::Value(name_right), right->m_levelmin, right->m_levelmax,
             ::cw::lib::Value(author_right), ::cw::lib::Value(right->m_fname), right->get_mtime_reversed()});
    }
}
