std::vector<::cw::lib::String> event_paths(const std::shared_ptr<::cw::lib::Window>& event) {
    std::vector<::cw::lib::String> result;
    if (!event || event->title.empty()) return result;
    std::size_t begin = 0;
    while (begin <= event->title.size()) {
        const auto end = event->title.find('\n', begin);
        auto path = event->title.substr(begin, end == ::cw::lib::String::npos ? end : end - begin);
        if (!path.empty() && path.back() == '\r') path.pop_back();
        if (!path.empty()) result.push_back(std::move(path));
        if (end == ::cw::lib::String::npos) break;
        begin = end + 1;
    }
    return result;
}

