// Python のアクセラレーター・ボタンのコールバックに合わせる。 共通ツリーに
// フォーカスがある場合は選択ノードを折り畳み、それ以外では有効な下部ボタン間でフォ
// ーカスを移す。 張り紙のページ移動は change_page() を直接使う。
void ScenarioSelect::OnPrevButton(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    sync_ui();
    const auto index = m_presentation_state.tree_selected_node_index;
    if (m_presentation_auxiliary_focus == -2 && m_presentation_state.tree_visible && index >= 0 &&
        static_cast<std::size_t>(index) < m_presentation_state.tree_nodes.size()) {
        auto item = std::make_shared<::cw::lib::Window>();
        item->id = index;
        item->title = m_presentation_state.tree_nodes[static_cast<std::size_t>(index)].path;
        OnTreeItemCollapsed(std::move(item));
        return;
    }
    focus_footer_button(-1);
}

// Python のアクセラレーター・ボタンのコールバックに合わせる。 共通の前・次の操作と
// DialogSideNavigation は、別の経路として張り紙のページ移動を維持する。
void ScenarioSelect::OnNextButton(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    sync_ui();
    const auto index = m_presentation_state.tree_selected_node_index;
    if (m_presentation_auxiliary_focus == -2 && m_presentation_state.tree_visible && index >= 0 &&
        static_cast<std::size_t>(index) < m_presentation_state.tree_nodes.size()) {
        const auto& node = m_presentation_state.tree_nodes[static_cast<std::size_t>(index)];
        if ((node.icon_index == 4 || node.icon_index == 5) && !node.expanded) {
            auto item = std::make_shared<::cw::lib::Window>();
            item->id = index;
            item->title = node.path;
            OnTreeItemExpanded(std::move(item));
        }
        return;
    }
    focus_footer_button(1);
}

void ScenarioSelect::OnMouseWheel(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!arg_event) return;
    // Py はホイールのコールバックから wx.ID_UP/ID_DOWN のボタンイベントを送る。
    // この旧形式の入口も、共通 Presentation と同じ張り紙のページ移動経路へつなぐ。
    change_page(arg_event->id > 0 ? -1 : 1);
}

