void ScenarioSelect::OnFind(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (m_processing_typed || m_finished_typed) return;
    std::vector<::cw::lib::Integer> types;
    switch (m_narrow_type_typed) {
    case 1: types = {::cw::scenariodb::g_DATA_TITLE}; break;
    case 2: types = {::cw::scenariodb::g_DATA_DESC}; break;
    case 3: types = {::cw::scenariodb::g_DATA_AUTHOR}; break;
    case 4: types = {::cw::scenariodb::g_DATA_LEVEL}; break;
    case 5: types = {::cw::scenariodb::g_DATA_FNAME}; break;
    default: types = {::cw::scenariodb::g_DATA_TITLE, ::cw::scenariodb::g_DATA_DESC,
                      ::cw::scenariodb::g_DATA_AUTHOR, ::cw::scenariodb::g_DATA_LEVEL,
                      ::cw::scenariodb::g_DATA_FNAME}; break;
    }
    if (m_search_text.empty()) {
        scenario_select_play_sound("error");
        // Python の OnNextButton と同様、ここでは選択シナリオではなくフォーカスを移す。
        focus_footer_button(1, true);
        request_dialog_presentation_refresh();
        return;
    }
    if (!m_db_typed) throw std::logic_error("scenario database is required");
    if (m_narrow_type_typed == 4) {
        if (!::cw::scenariodb::parse_level_search(m_search_text)) {
            scenario_select_play_sound("error");
            return;
        }
    }
    m_no_treechangedsound_typed = true;
    m_processing_typed = true;
    sync_ui();
    std::vector<::cw::lib::Value> values;
    try {
        for (const auto& header : m_db_typed->find_headers(types, m_search_text, current_skintype()))
            if (header) values.emplace_back(std::static_pointer_cast<::cw::lib::Object>(header));
    } catch (...) {
        m_no_treechangedsound_typed = false;
        m_processing_typed = false;
        sync_ui();
        throw;
    }
    scenario_select_play_sound("harvest");
    _set_findresult(std::move(values), false, true, -1);
    m_no_treechangedsound_typed = false;
    m_processing_typed = false;
    enable_btn();
    request_dialog_presentation_refresh();
}

void ScenarioSelect::_set_findresult(std::vector<::cw::lib::Value> arg_headers, bool arg_selfirstheader, bool arg_expand, ::cw::lib::Integer arg_selindex)
{
    std::shared_ptr<FindResult> result;
    const auto root_key = cache_key(ScenarioDirectory(m_scedir_typed));
    const auto root_it = m_scenario_cache_typed.find(root_key);
    if (root_it != m_scenario_cache_typed.end()) {
        for (const auto& candidate : root_it->second) {
            if (const auto* found = std::get_if<std::shared_ptr<FindResult>>(&candidate); found && *found) {
                result = *found;
                break;
            }
        }
    }
    if (!result) result = std::make_shared<FindResult>();
    result->initialize();
    result->m_headers=arg_headers;
    auto found=findresult_candidates(*result);
    if (arg_headers.size()>1 && !found.empty() &&
        std::holds_alternative<std::shared_ptr<::cw::header::ScenarioHeader>>(found.front())) {
        for (const auto& candidate:found) {
            const auto* header=std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&candidate);
            if (!header) throw std::logic_error("mixed result cannot be sorted as scenario headers");
            result->m_typed_headers.push_back(*header);
        }
        result->m_typed_headers=_sort_headers(std::move(result->m_typed_headers));
        result->m_headers.clear();
        for (const auto& header:result->m_typed_headers)
            result->m_headers.emplace_back(std::static_pointer_cast<::cw::lib::Object>(header));
    }
    m_find_result_typed = result;
    m_find_result = result;
    const auto result_key = cache_key(ScenarioDirectory(result));
    // 検索・データベースの順序を維持し、表示の並べ替えで書き換えない。
    m_scenario_cache_typed[result_key] = found;
    auto& root = m_scenario_cache_typed[root_key];
    root.erase(std::remove_if(root.begin(), root.end(), [](const ScenarioCandidate& candidate) {
        return std::holds_alternative<std::shared_ptr<FindResult>>(candidate);
    }), root.end());
    root.insert(root.begin(), result);
    const bool tree_visible = !m_tree.is_none() ||
        (::cw::g_cwpy && ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_show_paperandtree);
    const bool select_child = !found.empty() &&
        (arg_selfirstheader || (tree_visible && arg_selindex >= 0));
    if (select_child) {
        m_nowdir_typed = result;
        m_dirstack_typed = {{ScenarioDirectory(m_scedir_typed), "/find_result"}};
    } else {
        // Py と同様、検索後はルートで結果フォルダーを選択する。 以前のデ
        // ィレクトリーや戻り先の階層を保持したまま、その子だけを公開しない。
        m_nowdir_typed = m_scedir_typed;
        m_dirstack_typed.clear();
    }
    if (tree_visible && (arg_expand || select_child)) m_expanded_tree_paths.insert(result_key);
    else m_expanded_tree_paths.erase(result_key);
    m_tree_first_row = 0;
    m_tree_ensure_selection = true;
    m_source_candidates_typed = current_candidates(false);
    m_candidates_typed.clear();
    for (const auto& candidate : m_source_candidates_typed)
        if (candidate_is_showing(candidate)) m_candidates_typed.push_back(candidate);
    if (m_candidates_typed.empty()) m_index = 0;
    else m_index = select_child && arg_selindex >= 0
        ? std::clamp<::cw::lib::Integer>(arg_selindex, 0, static_cast<::cw::lib::Integer>(m_candidates_typed.size()) - 1) : 0;
    sync_legacy_list();
    _update_saveddirstack();
    // Python版は検索結果を次回ダイアログ起動用に即時保存する。
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting)
        ::cw::g_cwpy->m_setting->m_lastfindresult = get_findresult();
    _update_pagelabel();
    enable_btn();
    request_dialog_presentation_refresh();
}

