void ScenarioSelect::OnBookmark(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    scenario_select_play_sound("page");
    // ポインターとキーボードの入口で、同じポップアップ起動処理を使う。
    m_presentation_menu = 8;
    m_presentation_menu_row = 0;
    m_presentation_menu_first = 0;
    m__add_bookmark = ! _is_specialselected();
    m__arrange_bookmark = ::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata &&
                          !(*::cw::g_cwpy->m_ydata)->m_bookmarks.empty();
    create_bookmarkmenu();
}

void ScenarioSelect::OnBookmark2(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (!scenario_layout_metrics(&m_presentation_state).show_top_row) return;
    OnBookmark(std::move(arg_event));
}

bool ScenarioSelect::_is_specialselected()
{
    return m_candidates_typed.empty() || m_index < 0 || static_cast<std::size_t>(m_index) >= m_candidates_typed.size() ||
           std::holds_alternative<std::shared_ptr<FindResult>>(m_candidates_typed[static_cast<std::size_t>(m_index)]);
}

void ScenarioSelect::create_bookmarkmenu()
{
    m_bookmarkmenu = ::cw::lib::Value(std::make_shared<::cw::lib::Menu>());
    sync_ui();
    request_dialog_presentation_refresh();
}

void ScenarioSelect::OnAddBookmark(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    auto selected = get_selected();
    const auto path = std::get<1>(selected);
    if (std::get<0>(selected).empty() || path.empty()) return;
    auto name = std::get<0>(selected).back();
    if (name == "/find_result") return;
#if defined(_WIN32)
    if (name.size() >= 4 && lower_string(name.substr(name.size() - 4)) == ".lnk")
        name.resize(name.size() - 4);
#endif
    if (m_index >= 0 && static_cast<std::size_t>(m_index) < m_candidates_typed.size()) {
        const auto& candidate = m_candidates_typed[static_cast<std::size_t>(m_index)];
        if (const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&candidate);
            header && *header) {
            const auto header_name = value_string((*header)->m_name);
            if (!header_name.empty()) name = header_name;
        }
    }
    scenario_select_play_sound("signal");
    const auto title = ::cw::g_cwpy && ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_msgs
        ? ::cw::g_cwpy->m_setting->m_msgs->get("message", "メッセージ")
        : ::cw::lib::String("メッセージ");
    const auto prompt = ::cw::g_cwpy && ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_msgs
        ? ::cw::g_cwpy->m_setting->m_msgs->get("add_bookmark_message", "%sをブックマークへ追加しますか？")
        : ::cw::lib::String("%sをブックマークへ追加しますか？");
    if (m_host_services &&
        !m_host_services->confirm(title, format_scenario_message(prompt, name)))
        return;
    if (::cw::g_cwpy && ::cw::g_cwpy->m_ydata && *::cw::g_cwpy->m_ydata) {
        (*::cw::g_cwpy->m_ydata)->add_bookmark(std::get<0>(selected), path);
        scenario_select_play_sound("harvest");
        m_bookmarkpath = path;
        m_bookmarkmenu = ::cw::lib::Value{};
        sync_ui();
    }
}

::cw::dialog::etc::BookmarkPresentation ScenarioSelect::project_bookmark(
    const ::cw::dialog::etc::Bookmark& bookmark)
{
    auto row = ::cw::dialog::etc::resolve_bookmark(bookmark, m_scedir_typed, m_db_typed, current_skintype());
    if (row.header) {
        row.icon = is_playing(row.header) ? "SUMMARY_PLAYING"
                 : is_complete(row.header) ? "SUMMARY_COMPLETE"
                 : is_invisible(row.header) ? "SUMMARY_INVISIBLE" : "SUMMARY";
        row.enabled = candidate_is_showing(ScenarioCandidate(row.header));
    }
    return row;
}

void ScenarioSelect::OnArrangeBookmark(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata) return;
    auto& ydata = *::cw::g_cwpy->m_ydata;
    if (ydata->m_bookmarks.empty()) return;
    scenario_select_play_sound("click");
    auto parent = std::make_shared<::cw::lib::Window>();
    parent->native_handle = m_parent_native_handle;
    m_bookmark_dialog = std::make_shared<::cw::dialog::etc::BookmarkDialog>();
    m_bookmark_dialog->initialize(std::move(parent), m_scedir_typed, m_db_typed,
        [this](const ::cw::dialog::etc::Bookmark& bookmark) { return project_bookmark(bookmark); });
    (void)::cw::dialog::show_common_modal_presentation(m_bookmark_dialog);
}

void ScenarioSelect::OnOpenBookmark(::cw::lib::Integer arg_index)
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_ydata || !*::cw::g_cwpy->m_ydata) return;
    const auto& bookmarks = (*::cw::g_cwpy->m_ydata)->m_bookmarks;
    if (arg_index < 0 || static_cast<std::size_t>(arg_index) >= bookmarks.size()) return;
    const auto& [bookmark, bookmark_path] = bookmarks[static_cast<std::size_t>(arg_index)];
    // キーワードを消去する前に、メニューと同じ絞り込み条件を再確認する。
    if (!project_bookmark(bookmarks[static_cast<std::size_t>(arg_index)]).enabled) return;
    scenario_select_play_sound("equipment");
    if (!m_search_text.empty()) set_search({}, m_narrow_type_typed);
    set_selected(bookmark, bookmark_path, true, false, std::nullopt);
}

void ScenarioSelect::OnLeftDClick(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    // 共通 Presentation では、張り紙中央の決定と端の移動を別のコント
    // ロールとして扱う。 ネイティブのポインター経路は両方のクリックを処理する。
}

void ScenarioSelect::OnLeftDClick2(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    _tree_dclick();
}

void ScenarioSelect::_tree_dclick()
{
    if (!m_candidates_typed.empty()) {
        const auto& selected = m_candidates_typed[static_cast<std::size_t>(m_index)];
        if (is_scenario_candidate(selected)) {
            const bool has_view_button = !::cw::g_cwpy || !::cw::g_cwpy->m_setting ||
                                         !::cw::g_cwpy->m_setting->m_show_paperandtree;
            if (has_view_button) OnClickViewBtn({});
            else OnClickYesBtn(nullptr);
            return;
        }
        const auto path = std::holds_alternative<std::shared_ptr<FindResult>>(selected)
            ? ::cw::lib::String("/find_result") : candidate_path(selected);
        if (path.empty()) return;
        ScenarioDirectory directory = path;
        if (const auto* find = std::get_if<std::shared_ptr<FindResult>>(&selected)) directory = *find;
        const auto key = cache_key(directory);
        auto item = std::make_shared<::cw::lib::Window>();
        item->title = path;
        if (m_expanded_tree_paths.contains(key)) {
            scenario_select_play_sound("page");
            item->id = m_presentation_state.tree_selected_node_index;
            _collapse_tree(item);
        } else {
            scenario_select_play_sound("equipment");
            item->id = m_presentation_state.tree_selected_node_index;
            _expandeditem(item, path, {});
        }
        sync_ui();
    }
}

// ネイティブのイベントは wx のキー・フォーカスオブジェクトではなく論理
// ID を渡す。 修飾キー、ツリー・下部のフォーカス、IME 変換は共通
// の意味上のキー・操作経路で管理し、この互換入口に別の入力規則を作らない。
void ScenarioSelect::OnKeyDown(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (arg_event && arg_event->id == 13) {
        // Python の OnKeyDown と同様、Enter はシナリオを決定し、ダブ
        // ルクリックはプレビューする。 両方を _tree_dclick() へ流さない。
        if (can_decide()) OnClickYesBtn(nullptr);
        else _tree_dclick();
    }
}

bool ScenarioSelect::can_clickcenter()
{
    // Python版はシナリオの「決定」だけでなく、フォルダ/FindResultの
    // 「見る」ボタンも有効なら中央クリックを受け付ける。
    return value_bool(m_yesbtn);
}

std::tuple<std::vector<::cw::lib::String>, ::cw::lib::String> ScenarioSelect::get_selected()
{
    std::vector<::cw::lib::String> result;
    // Python版は保存済みスナップショットがない場合は未選択として扱う。
    // 現在表示中の候補を暗黙に返すと、フォルダ移動直後のbookmark/installが
    // 以前の経路を壊すため、保存値だけを正本にする。
    if (m_candidates_typed.empty() || m_saved_list_typed.empty()) return {result, {}};
    const auto& list = m_saved_list_typed;
    const auto index = value_integer(m__saved_index);
    if (list.empty() || index < 0 || static_cast<std::size_t>(index) >= list.size())
        return {result, {}};
    // 保存した階層が空なら、保存済み選択がルートにあることを表す。 ス
    // ナップショットの欠落とみなして、後の移動先の祖先で置き換えない。
    for (const auto& entry : m_saved_dirstack_typed) {
        const auto& name = std::get<1>(entry);
        result.push_back(name);
    }
    const auto& selected = list[static_cast<std::size_t>(index)];
    if (const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&selected); header && *header) {
        const auto path = (*header)->get_fpath();
        result.push_back((*header)->m_fname);
        return {result, path_text(std::filesystem::absolute(std::filesystem::u8path(path)))};
    }
    if (const auto* path = std::get_if<::cw::lib::String>(&selected); path && !path->empty()) {
        result.push_back(basename_of(*path));
        return {result, path_text(std::filesystem::absolute(std::filesystem::u8path(*path)))};
    }
    if (std::holds_alternative<std::shared_ptr<FindResult>>(selected)) return {{"/find_result"}, {}};
    return {result, {}};
}

std::vector<::cw::lib::String> ScenarioSelect::get_findresult()
{
    std::vector<::cw::lib::String> result;
    if (!m_find_result || !*m_find_result) return result;
    for (const auto& candidate:findresult_candidates(**m_find_result)) result.push_back(candidate_path(candidate));
    return result;
}

std::vector<::cw::lib::Value> ScenarioSelect::_get_nowlist(std::optional<::cw::lib::Value> arg_nowdir, bool arg_update)
{
    ScenarioDirectory nowdir = m_nowdir_typed;
    if (arg_nowdir) {
        if (auto result = value_findresult(*arg_nowdir)) nowdir = result;
        else if (const auto* path = std::get_if<::cw::lib::String>(&arg_nowdir->storage())) nowdir = *path;
    }
    if (const auto* path = std::get_if<::cw::lib::String>(&nowdir)) {
        const auto target = ::cw::util::get_linktarget(*path);
        if (!target.empty()) nowdir = target;
    }
    const auto values = [this](const std::vector<ScenarioCandidate>& candidates) {
        std::vector<::cw::lib::Value> result;
        for (const auto& candidate : candidates) result.push_back(candidate_to_value(candidate));
        return result;
    };
    // Python の読み取り処理と同様、移動も現在一覧の絞り込み・公開も行わない。
    if (!arg_update) {
        const auto cached = m_scenario_cache_typed.find(cache_key(nowdir));
        if (cached != m_scenario_cache_typed.end()) return values(cached->second);
    }
    std::vector<ScenarioCandidate> candidates;
    if (const auto* result = std::get_if<std::shared_ptr<FindResult>>(&nowdir); result && *result) {
        candidates=findresult_candidates(**result);
    } else if (const auto* path = std::get_if<::cw::lib::String>(&nowdir); path && !path->empty()) {
        auto target = ::cw::util::get_linktarget(*path);
        if (target.empty()) target = *path;
        // scedir直下には検索結果ディレクトリを常に先頭へ置く。
        // Python版はscetable[scedir]を参照するため、ここで明示的に反映する。
        if (*path == m_scedir_typed && m_find_result_typed)
            candidates.emplace_back(m_find_result_typed);
        if (m_db_typed) {
            if (arg_update) m_db_typed->update(target, current_skintype(), true, true);
            for (const auto& header : m_db_typed->search_dpath(target, true, current_skintype(), arg_update)) if (header) candidates.emplace_back(header);
        }
        for (const auto& directory : ::cw::dialog::scenarioinstall::get_dpaths(target))
            candidates.emplace_back(directory);
    }
    return values(candidates);
}

void ScenarioSelect::set_selected(std::vector<::cw::lib::String> arg_spaths, ::cw::lib::String arg_fullpath, bool arg_opendir, bool arg_updatetree, std::optional<std::vector<::cw::lib::Value>> arg_findresults)
{
    using S = ::cw::lib::String;
    // Python と同様、経路の最後の要素を現在ディレクトリー内の選
    // 択項目とし、それより前の要素だけを開く。 最後のファイルまで load_directory()
    // に渡して、ファイルをディレクトリーとして扱わない。
    // たどった経路外のツリー内容は要求された時だけ更新し、現
    // 在のディレクトリー内容はどちらの場合も別途更新する。
    if (arg_updatetree && is_tree_visible()) m_scenario_cache_typed.erase(cache_key(ScenarioDirectory(m_scedir_typed)));
    const bool previous_processing = m_processing_typed;
    m_processing_typed = true;
    m_decision_pending_typed = false;

    auto make_findresult = [](const std::vector<::cw::lib::Value>& values) {
        auto result=std::make_shared<FindResult>();
        result->m_headers=values;
        return result;
    };

    if (arg_findresults && !arg_findresults->empty() &&
        std::find(arg_spaths.begin(), arg_spaths.end(), "/find_result") != arg_spaths.end()) {
        // 検索結果はrootの仮想ディレクトリにも登録し、後続の
        // "/find_result" 経路から同じオブジェクトを参照できるようにする。
        m_find_result_typed = make_findresult(*arg_findresults);
        m_find_result = m_find_result_typed;
        std::vector<::cw::lib::Value> copied = *arg_findresults;
        _set_findresult(std::move(copied), false, false, -1);
    }

    bool resolved = false;
    if (!arg_spaths.empty()) {
        ScenarioDirectory current = m_scedir_typed;
        m_dirstack_typed.clear();
        bool valid = true;
        const std::size_t last = arg_spaths.size() - 1;
        for (std::size_t i = 0; i < last; ++i) {
            const auto& part = arg_spaths[i];
            if (part == "/find_result" && arg_findresults.has_value() && m_find_result_typed) {
                m_dirstack_typed.emplace_back(ScenarioDirectory(m_scedir_typed), part);
                current = m_find_result_typed;
                continue;
            }
            if (const auto* find = std::get_if<std::shared_ptr<FindResult>>(&current); find && *find) {
                // 検索結果がフォルダ1件のbookmark経路では、FindResult内の
                // 文字列パスを次の実ディレクトリへ解決する。
                bool found_path = false;
                for (const auto& value : (*find)->m_headers) {
                    const auto candidate = value_string(value);
                    if (!candidate.empty() && normcase_component(basename_of(candidate)) == normcase_component(part) &&
                        ::cw::util::path_is_directory(candidate)) {
                        // Python版はbookmark由来のFindResult内フォルダでは、
                        // FindResult自身ではなく元パスの親ディレクトリをstackへ保存する。
                        const auto parent = path_text(std::filesystem::u8path(candidate).parent_path());
                        m_dirstack_typed.emplace_back(parent.empty() ? current : ScenarioDirectory(parent), part);
                        current = ::cw::util::get_linktarget(candidate);
                        found_path = true;
                        break;
                    }
                }
                if (found_path) continue;
            }
            const auto* base = std::get_if<::cw::lib::String>(&current);
            if (!base || base->empty()) { valid = false; break; }
            const auto next = path_text(std::filesystem::u8path(*base) / std::filesystem::u8path(part));
            const auto target = ::cw::util::get_linktarget(next);
            if (target.empty() || !::cw::util::path_exists(target)) { valid = false; break; }
            m_dirstack_typed.emplace_back(current, part);
            current = target;
        }
        if (valid) {
            m_nowdir_typed = current;
            load_directory(m_nowdir_typed, true);
            const auto& wanted = arg_spaths.back();
            for (std::size_t i = 0; i < m_candidates_typed.size(); ++i) {
                const auto& candidate = m_candidates_typed[i];
                const auto name = std::holds_alternative<std::shared_ptr<FindResult>>(candidate)
                                      ? ::cw::lib::String("/find_result")
                                      : (is_scenario_candidate(candidate)
                                             ? std::get<std::shared_ptr<::cw::header::ScenarioHeader>>(candidate)->m_fname
                                             : basename_of(candidate_path(candidate)));
                if (normcase_component(name) == normcase_component(wanted)) {
                    m_index = static_cast<::cw::lib::Integer>(i);
                    resolved = true;
                    break;
                }
            }
            // Python と同様、共通ツリーでは選択フォルダーを展開し
            // つつ、張り紙表示の現在ディレクトリーはその親のままにする。
            if(resolved&&arg_opendir&&candidate_is_directory(m_candidates_typed[static_cast<std::size_t>(m_index)]))
                m_expanded_tree_paths.insert(cache_key(ScenarioDirectory(candidate_path(m_candidates_typed[static_cast<std::size_t>(m_index)]))));
        }
    }

    if (!resolved) {
        std::vector<::cw::lib::Value> supplied;
        ::cw::lib::Integer supplied_index = -1;
        std::optional<::cw::lib::Value> last_header;
        const auto as_header = [](const ::cw::lib::Value& value) {
            const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage());
            return object ? std::dynamic_pointer_cast<::cw::header::ScenarioHeader>(*object)
                          : std::shared_ptr<::cw::header::ScenarioHeader>{};
        };
        const auto lookup = [this](const S& path) {
            return m_db_typed ? m_db_typed->search_path(path, current_skintype())
                             : std::optional<std::shared_ptr<::cw::header::ScenarioHeader>>{};
        };
        if (arg_findresults && !arg_findresults->empty()) {
            const auto key = ::cw::util::get_keypath(arg_fullpath);
            if (std::holds_alternative<::cw::lib::String>(arg_findresults->front().storage())) {
                for (const auto& value : *arg_findresults) {
                    const auto* path = std::get_if<::cw::lib::String>(&value.storage());
                    if (!path) throw std::invalid_argument("string find result expected");
                    if (const auto header = lookup(*path); header && *header)
                        supplied.emplace_back(std::static_pointer_cast<::cw::lib::Object>(*header));
                    else if (::cw::util::path_exists(*path)) supplied.push_back(value);
                    else continue;
                    if (supplied_index == -1 && key == ::cw::util::get_keypath(*path))
                        supplied_index = static_cast<::cw::lib::Integer>(supplied.size()) - 1;
                }
            } else {
                supplied = *arg_findresults;
                for (std::size_t i = 0; i < supplied.size(); ++i) {
                    last_header = supplied[i];
                    if (value_findresult(supplied[i])) throw std::invalid_argument("nested find result");
                    S path;
                    if (const auto header = as_header(supplied[i])) path = header->get_fpath();
                    else if (const auto* text = std::get_if<S>(&supplied[i].storage())) {
                        if (!::cw::util::path_exists(*text)) continue;
                        path = *text;
                    } else throw std::invalid_argument("scenario header or path expected");
                    if (key == ::cw::util::get_keypath(path)) {
                        supplied_index = static_cast<::cw::lib::Integer>(i);
                        break;
                    }
                }
            }
            if (!supplied.empty() && supplied_index == -1) {
                if (const auto header = lookup(arg_fullpath); header && *header)
                    supplied.emplace_back(std::static_pointer_cast<::cw::lib::Object>(*header));
                else if (::cw::util::path_exists(arg_fullpath)) supplied.emplace_back(arg_fullpath);
                std::vector<::cw::lib::Value> paths;
                std::vector<std::shared_ptr<::cw::header::ScenarioHeader>> headers;
                for (const auto& value : supplied) {
                    if (const auto header = as_header(value)) headers.push_back(header);
                    else paths.push_back(value);
                }
                supplied = std::move(paths);
                for (const auto& header : _sort_headers(std::move(headers)))
                    supplied.emplace_back(std::static_pointer_cast<::cw::lib::Object>(header));
                // Py の代替動作をそのまま維持し、新たに追加した fullpath ではなく最
                // 後に渡された header を選択する。 文字列だけの分岐ではそのローカル変
                // 数が未定義となり UnboundLocalError が出るため、 ネイティ
                // ブでは対応する言語境界の logic_error とし、架空の行を作らない。
                if (!last_header) throw std::logic_error("unbound find result header");
                for (std::size_t i = 0; i < supplied.size(); ++i) {
                    const auto* old_object = std::get_if<::cw::lib::ObjectPtr>(&last_header->storage());
                    const auto* new_object = std::get_if<::cw::lib::ObjectPtr>(&supplied[i].storage());
                    const auto* old_path = std::get_if<S>(&last_header->storage());
                    const auto* new_path = std::get_if<S>(&supplied[i].storage());
                    if ((old_object && new_object && *old_object == *new_object) ||
                        (old_path && new_path && *old_path == *new_path)) {
                        supplied_index = static_cast<::cw::lib::Integer>(i);
                        break;
                    }
                }
            }
            if (!supplied.empty() && supplied_index >= 0) {
                _set_findresult(supplied, true, true, supplied_index);
                resolved = true;
            }
        }
        if (supplied.empty() && !arg_fullpath.empty() && m_db_typed) {
            if (auto header = m_db_typed->search_path(arg_fullpath, current_skintype()); header && *header && is_showing(*header)) {
                std::vector<::cw::lib::Value> values{::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*header))};
                _set_findresult(std::move(values), true, true, -1);
                resolved = true;
            }
        }
        if (supplied.empty() && !resolved && !arg_fullpath.empty() && ::cw::util::path_is_directory(arg_fullpath)) {
            std::vector<::cw::lib::Value> values{::cw::lib::Value(arg_fullpath)};
            _set_findresult(std::move(values), true, true, -1);
            resolved = true;
        }
    }

    if (!resolved) {
        m_nowdir_typed = m_scedir_typed;
        m_dirstack_typed.clear();
        load_directory(m_nowdir_typed, true);
        m_index = 0;
    }
    sync_legacy_list();
    m_processing_typed = previous_processing;
    _update_saveddirstack();
    // Python の set_selected と同様、最後に self.draw(True)
    // に相当する描画を行う。 これがないと、シナリオから戻った際の検
    // 索結果など、ここで選択した張り紙のアニメーションが始まらない。
    // アニメーション用のフレームは _draw_impl で取得する。
    draw(true);
    enable_btn();
}

void ScenarioSelect::_update_saveddirstack()
{
    if (m_dirstack_typed.size() == 1) {
        if (const auto* path = std::get_if<::cw::lib::String>(&std::get<0>(m_dirstack_typed.front())); path && !path->empty() && (*path)[0] == '/') return;
    }
    m_saved_dirstack_typed = m_dirstack_typed;
    m_saved_list_typed = m_candidates_typed;
    m__saved_index = ::cw::lib::Value(m_index);
    m_dirstack.clear();
    for (const auto& [directory, name] : m_dirstack_typed) {
        if (const auto* path = std::get_if<::cw::lib::String>(&directory))
            m_dirstack.emplace_back(::cw::lib::Value(*path), name);
        else if (const auto* result = std::get_if<std::shared_ptr<FindResult>>(&directory); result && *result)
            m_dirstack.emplace_back(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*result)), name);
    }
    m_nowdir = std::visit([](const auto& directory) -> ::cw::lib::Value {
        using T = std::decay_t<decltype(directory)>;
        if constexpr (std::is_same_v<T, ::cw::lib::String>) return directory;
        else return directory ? ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(directory)) : ::cw::lib::Value{};
    }, m_nowdir_typed);
    m_scedir = ::cw::lib::Value(m_scedir_typed);
    m__saved_dirstack = ::cw::lib::Value{};
    m__saved_list = ::cw::lib::Value{};
}

void ScenarioSelect::index_changed()
{
    _update_saveddirstack();
    sync_ui();
}

void ScenarioSelect::OnDropFiles(std::shared_ptr<::cw::lib::Window> arg_event)
{
    dialog_presentation_drop_files(event_paths(arg_event));
}

void ScenarioSelect::dialog_presentation_drop_files(const std::vector<std::string>& paths)
{
    if (paths.empty() || m_processing_typed || m_finished_typed) return;
    m_presentation_menu = 0;
    m_search_input.dragging = false;
    request_dialog_presentation_refresh();
    auto [headers_with_link, notscenariofiles] = _to_headers(paths, true);
    if (headers_with_link.empty()) {
        scenario_select_play_sound("error");
        return;
    }
    const bool allow_install = !::cw::g_cwpy || !::cw::g_cwpy->m_setting ||
                               ::cw::g_cwpy->m_setting->m_can_installscenariofromdrop;
    if (allow_install) {
        auto [headers, install_files] = _to_headers(paths, false);
        if (!headers.empty()) {
            _install_scenario(std::move(headers), std::move(headers_with_link), std::move(install_files));
            return;
        }
    }
    _show_selectedscenario(std::move(headers_with_link));
}

void ScenarioSelect::cancel_document_request()
{
    if (!m_document_token) return;
    m_document_token.reset();
    m_document_ticket.reset();
    m_processing_typed = false;
    request_dialog_presentation_refresh();
}

bool ScenarioSelect::request_document(DocumentAction action, DocumentRequest start)
{
    namespace doc = ::cw::lib::documents;
    const auto weak = weak_from_this();
    if (m_processing_typed || m_finished_typed || m__quit || document_request_pending() || weak.expired()) return false;
    doc::Request request;
    ::cw::lib::String source;
    if (action == DocumentAction::Install || action == DocumentAction::LinkScenario) {
        request.title = action == DocumentAction::Install
            ? "インストールするシナリオを選択" : "リンク先のシナリオを選択";
        request.multiple = true;
        // SDL のフィルターはファイル名のパターンではなく拡張子の一覧である。 Summary.xml
        // は選択後に既存のシナリオヘッダー検証で受け付ける。
        request.filters = {{"シナリオファイル (Summary.xmlを含む)","wsn;wsm;zip;lzh;cab;xml"},{"すべてのファイル","*"}};
        // インストールでは選択アーカイブを直ちに読み取り・コピーするため、プロバ
        // イダー URI に共通の上限付き一時保存経路を使える。 シナリオのリ
        // ンクは永続的な参照なので、実際のネイティブパスを保持する必要がある。
        if (action == DocumentAction::Install)
            request.transient_read_limit = 512u * 1024u * 1024u;
    } else {
        request.operation = doc::Operation::OpenFolder;
        if (action == DocumentAction::Move) {
            if (m_index<0 || static_cast<std::size_t>(m_index)>=m_candidates_typed.size() ||
                std::holds_alternative<std::shared_ptr<FindResult>>(m_candidates_typed[m_index])) return false;
            source = candidate_path(m_candidates_typed[m_index]);
            if (source.empty()) return false;
            request.title = "移動先を選択";
            request.initial_location = path_text(std::filesystem::u8path(source).parent_path());
        } else if (action == DocumentAction::Convert) {
            request.title = "カードワースのシナリオデータをカードワースパイ用に変換します。\n変換するシナリオのディレクトリを選択してください";
            request.initial_location = path_text(std::filesystem::current_path());
        } else if (action == DocumentAction::LinkDirectory) {
            request.title = "リンク先のフォルダを選択";
            request.initial_location = m_scedir_typed;
        } else return false;
    }
    if (!request.initial_location.empty()) {
        std::error_code error;
        const auto absolute = std::filesystem::absolute(std::filesystem::u8path(request.initial_location),error);
        if (!error) request.initial_location = path_text(absolute);
    }
    const auto token = std::make_shared<int>(0);
    const auto directory = m_nowdir_typed;
    const auto target = _get_installtarget();
    const auto database = m_db_typed;
    m_document_token = token;
    m_processing_typed = true;
    m_presentation_menu = 0;
    m_search_input.dragging = false;
    request_dialog_presentation_refresh();
    const auto done = [weak,token,directory,target,database,source,action](doc::Result result) {
        const auto self = weak.lock();
        if (!self || self->m_document_token!=token) return;
        // 遅れて届いた選択を、別のフォルダー・データベース・選択項目へ適用しない。 ネ
        // イティブの選択画面を開いている間も、従来のモデルコールバックは実行され得る。
        const bool same_context = !self->m_finished_typed && !self->m__quit &&
            self->m_nowdir_typed==directory && self->m_db_typed==database &&
            self->_get_installtarget()==target && (action!=DocumentAction::Move ||
                (self->m_index>=0 && static_cast<std::size_t>(self->m_index)<self->m_candidates_typed.size() &&
                 self->candidate_path(self->m_candidates_typed[self->m_index])==source));
        self->cancel_document_request();
        if (!same_context || result.status==doc::Status::Cancelled) return;
        const auto error = [&](const ::cw::lib::String& text) {
            if (self->m_host_services) self->m_host_services->message("メッセージ",text);
        };
        if (result.status!=doc::Status::Success || result.documents.empty() ||
            ((action!=DocumentAction::Install && action!=DocumentAction::LinkScenario) &&
             result.documents.size()!=1)) {
            error(result.error.empty() ? "ファイルまたはフォルダを選択できませんでした。" : result.error);
            return;
        }
        std::vector<::cw::lib::String> paths;
        for (const auto& document : result.documents) {
            if (document.kind!=doc::LocationKind::NativePath || document.location.empty()) {
                error("選択した文書をローカルファイルとして使用する処理は、この環境では未対応です。");
                return;
            }
            paths.push_back(document.location);
        }
        // result は、同期的なモデル操作が入力を読み終えるまでアクセス権を
        // 保持する。 URI を std::filesystem へ渡さない。
        try { self->apply_document_selection(action,paths); }
        catch (const std::exception& ex) { error("選択したファイルの処理に失敗しました。\n"+::cw::lib::String(ex.what())); }
        catch (...) { error("選択したファイルの処理に失敗しました。"); }
        self->request_dialog_presentation_refresh();
    };
    if (!start) start = ::cw::dialog::request_presentation_document;
    try {
        auto ticket = start(request,done);
        if (m_document_token==token) {
            m_document_ticket = std::move(ticket);
            if (!m_document_ticket || !m_document_ticket->pending())
                done({doc::Status::Failed,{},"ファイル選択を開始できませんでした。"});
        }
    } catch (const std::exception& error) { done({doc::Status::Failed,{},error.what()}); }
      catch (...) { done({doc::Status::Failed,{},"ファイル選択を開始できませんでした。"}); }
    return true;
}

void ScenarioSelect::apply_document_selection(DocumentAction action, const std::vector<::cw::lib::String>& paths)
{
    if (paths.empty() || m_processing_typed || m_finished_typed || m__quit) return;
    if (action == DocumentAction::Install) install_selected_paths(paths);
    else if (action == DocumentAction::Move) {
        auto event = std::make_shared<::cw::lib::Window>();
        event->title = paths.front(); // 単一フォルダーとして扱い、改行区切りにはしない。
        OnMoveBtn(std::move(event));
    } else if (action == DocumentAction::Convert) conv_scenario(paths.front());
    else if (action == DocumentAction::LinkScenario) create_scenario_links(paths);
    else if (action == DocumentAction::LinkDirectory) create_directory_link(paths.front());
}

void ScenarioSelect::OnInstallBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (m_processing_typed || m_finished_typed) return;
    const auto paths = event_paths(arg_event); // 従来のコマンド転送専用。
    if (paths.empty()) request_document(DocumentAction::Install);
    else install_selected_paths(paths);
}

void ScenarioSelect::install_selected_paths(const std::vector<::cw::lib::String>& paths)
{
    if (paths.empty() || m_processing_typed || m_finished_typed) return;
    auto [headers_with_link, unused_files] = _to_headers(paths, true);
    (void)unused_files;
    if (headers_with_link.empty()) return;
    auto [headers, install_files] = _to_headers(paths, false);
    if (!headers.empty()) _install_scenario(std::move(headers), std::move(headers_with_link), std::move(install_files));
    else _show_selectedscenario(std::move(headers_with_link));
}

std::tuple<::cw::lib::String, ::cw::lib::String> ScenarioSelect::_get_installtarget()
{
    if (std::holds_alternative<std::shared_ptr<FindResult>>(m_nowdir_typed)) return {m_scedir_typed, {}};
    auto dpath = std::get<::cw::lib::String>(m_nowdir_typed);
    ::cw::lib::String selected_name;
    if (!m_candidates_typed.empty() && m_index >= 0 && static_cast<std::size_t>(m_index) < m_candidates_typed.size()) {
        const auto& selected = m_candidates_typed[static_cast<std::size_t>(m_index)];
        if (std::holds_alternative<std::shared_ptr<FindResult>>(selected)) {
            // Python版はFindResult選択時、現在の実ディレクトリを維持する。
        } else if (!is_scenario_candidate(selected)) {
            const auto path = candidate_path(selected);
            dpath = path;
            selected_name = basename_of(path);
        }
    }
    return {dpath, selected_name};
}

void ScenarioSelect::_select_installedpaths(::cw::lib::String arg_firstpath, ::cw::lib::String arg_seldname, std::vector<::cw::lib::String> arg_paths)
{
    std::vector<::cw::lib::String> selected;
    _update_saveddirstack();
    const auto prior = get_selected();
    selected = std::get<0>(prior);
    if (!selected.empty() && !arg_seldname.empty()) {
        selected.back() = arg_seldname;
        selected.push_back(basename_of(arg_firstpath));
    } else if (!arg_seldname.empty()) {
        selected = {arg_seldname, basename_of(arg_firstpath)};
    } else if (selected.empty()) {
        selected.push_back(basename_of(arg_firstpath));
    } else {
        selected.back() = basename_of(arg_firstpath);
    }
    set_selected(std::move(selected), std::move(arg_firstpath), true, true, [&] {
        std::vector<::cw::lib::Value> values;
        for (const auto& path : arg_paths) values.emplace_back(path);
        return values;
    }());
}

void ScenarioSelect::OnCreateDirBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    // Python と同様、子フォルダーがインストール先に
    // 選択されていても、表示中の項目と同じ場所へ作成する。
    const auto* directory=std::get_if<::cw::lib::String>(&m_nowdir_typed);
    if(!directory)return;
    if (!m_host_services) return;
    const auto candidate = ::cw::dialog::scenarioinstall::create_dir(
        nullptr, *directory, [this](const auto& prompt, const auto& initial) {
            return m_host_services->request_text(prompt, initial);
        });
    if (!candidate.empty()) {
        scenario_select_play_sound("harvest");
        _select_installedpaths(candidate, "", {});
    }
}

void ScenarioSelect::OnMoveBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (m_processing_typed || m_finished_typed) return;
    if (m_candidates_typed.empty()) return;
    if (m_index < 0 || static_cast<std::size_t>(m_index) >= m_candidates_typed.size()) return;
    const auto selected = m_candidates_typed[static_cast<std::size_t>(m_index)];
    if (std::holds_alternative<std::shared_ptr<FindResult>>(selected)) return;
    const auto source = candidate_path(selected);
    if (source.empty()) return;
    scenario_select_play_sound("click");
    ::cw::lib::String destination_text = arg_event ? arg_event->title : ::cw::lib::String{};
    if (destination_text.empty()) {
        request_document(DocumentAction::Move);
        return;
    }
    if (destination_text.empty()) return;
    const auto destination_dir = std::filesystem::u8path(::cw::util::normalize_path(
        ::cw::util::get_linktarget(destination_text)));
    if (destination_dir.empty()) return;
    auto destination = destination_dir / basename_of(source);
    const auto source_abs = std::filesystem::absolute(std::filesystem::u8path(source)).lexically_normal();
    const auto dest_abs = std::filesystem::absolute(destination).lexically_normal();
    const auto source_string = path_text(source_abs);
    const auto destination_string = path_text(dest_abs);
    const bool is_child = destination_string.size() > source_string.size() &&
                          ::cw::util::path_starts_with(destination_string, source_string);
    if (::cw::util::get_keypath(source_string) == ::cw::util::get_keypath(destination_string)) {
        // Py と同様、現在のディレクトリーを選んだ場合は何も変更せず成功とする。
        scenario_select_play_sound("harvest");
        return;
    }
    if (std::filesystem::is_directory(source_abs) && is_child) {
        scenario_select_play_sound("error");
        if (m_host_services) {
            m_host_services->message("メッセージ", "移動先は移動対象のサブフォルダです。");
        }
        return;
    }
    destination = std::filesystem::u8path(::cw::util::dupcheck_plus(path_text(destination), false, false));
    try {
        scenario_select_play_sound("harvest");
        ::cw::util::rename_file(path_text(source_abs), path_text(destination), false);
        if (std::filesystem::is_directory(destination) && m_db_typed) m_db_typed->rename_dir(source, path_text(destination));
        rebuild_candidates();
        std::vector<::cw::lib::String> selected_path;
        std::error_code route_error;
        const auto root = std::filesystem::absolute(
            std::filesystem::u8path(m_scedir_typed), route_error).lexically_normal();
        const auto target_directory = std::filesystem::absolute(destination_dir, route_error).lexically_normal();
        const auto relative_directory = target_directory.lexically_relative(root);
        if (!route_error) {
            if (!relative_directory.empty()) {
                for (const auto& component : relative_directory) {
                    const auto part = path_text(component);
                    if (!part.empty() && part != ".") selected_path.push_back(part);
                }
            } else if (target_directory != root) {
                // ファイルシステムのルートが異なる場合、字句上の相対パスは存在しない。 set_selected
                // に絶対ディレクトリーを最初の経路として解決させる。
                selected_path.push_back(path_text(target_directory));
            }
        } else {
            selected_path.push_back(path_text(destination_dir));
        }
        selected_path.push_back(basename_of(path_text(destination)));
        set_selected(std::move(selected_path), path_text(destination), true, true, std::nullopt);
    } catch (const std::exception&) {
        ::cw::util::print_ex(std::nullopt);
        scenario_select_play_sound("error");
        if (m_host_services)
            m_host_services->message("メッセージ", source + "の移動に失敗しました。");
    }
}

void ScenarioSelect::OnDeleteBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (m_candidates_typed.empty()) return;
    if (m_index < 0 || static_cast<std::size_t>(m_index) >= m_candidates_typed.size()) return;
    const auto selected = m_candidates_typed[static_cast<std::size_t>(m_index)];
    if (std::holds_alternative<std::shared_ptr<FindResult>>(selected)) return;
    const auto path = candidate_path(selected);
    if (path.empty()) return;
    scenario_select_play_sound("click");
    ::cw::lib::String name = std::holds_alternative<::cw::lib::String>(selected)
        ? basename_of(path) : candidate_name(selected);
    if (name.empty()) name = basename_of(path);
    // Python の確認処理が使う .lnk 機能を持つのは Windows だけである。
#ifdef _WIN32
    const bool shortcut = ::cw::util::path_is_file(path) &&
                          lower_ascii(path_text(std::filesystem::u8path(path).extension())) == ".lnk";
#else
    const bool shortcut = false;
#endif
    ::cw::lib::String message;
    if (const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&selected);
        header && *header) {
        const auto author = value_string((*header)->m_author);
        if (!author.empty()) name += "(" + author + ")";
        message = shortcut ? "「" + name + "」のショートカットを削除します。\nよろしいですか？"
                           : "「" + name + "」を削除します。\nよろしいですか？";
    } else if (shortcut) {
        name.resize(name.size() - 4);
        message = "ショートカット「" + name + "」を削除します。\nよろしいですか？";
    } else {
        message = "フォルダ「" + name +
                  "」を削除します。\nフォルダの中に存在する全てのサブフォルダとシナリオも削除されます。よろしいですか？";
    }
    if (arg_event) {
        if (arg_event->id != 1) return;
    } else {
        if (!m_host_services || !m_host_services->confirm("メッセージ", message)) return;
    }
    try {
        // Python版はtrashbox=True。util::removeはOSごとのごみ箱実装を
        // まとめて扱い、単純remove_allより復元可能性を保つ。
        scenario_select_play_sound("dump");
        const bool directory = ::cw::util::path_is_directory(path);
        ::cw::util::remove(path, true);
        if (directory && m_db_typed) m_db_typed->remove_dir(path);
        const auto* nowdir = std::get_if<::cw::lib::String>(&m_nowdir_typed);
        if (!nowdir) throw std::invalid_argument("ScenarioSelect.nowdir must be a directory path");
        if (m_db_typed) m_db_typed->update(*nowdir, current_skintype(), true, true);

        if (!m_tree.is_none()) {
            // Presentation の行は、TreeCtrl の選択項目の兄弟群に相当する共通
            // 表現である。 キャッシュ・データベースを再読み込みせずスナップショットを取り、Py
            // と同様、ヘルパーの失敗が呼び出し側の list.pop より先に起きるようにする。
            const auto& nodes = m_presentation_state.tree_nodes;
            const auto selected_node = m_presentation_state.tree_selected_node_index;
            if (selected_node < 0 || static_cast<std::size_t>(selected_node) >= nodes.size())
                throw std::invalid_argument("ScenarioSelect has no selected tree item");
            const auto parent = nodes[static_cast<std::size_t>(selected_node)].parent_index;
            const auto siblings = std::make_shared<ScenarioTreeItemWindow::Siblings>();
            std::vector<std::shared_ptr<ScenarioTreeItemWindow>> handles;
            std::shared_ptr<::cw::lib::Window> selected_handle;
            for (std::size_t i = 0; i < nodes.size(); ++i) {
                if (nodes[i].parent_index != parent) continue;
                auto handle = make_tree_item(nullptr, siblings);
                handle->id = nodes[i].candidate_index;
                if (i == static_cast<std::size_t>(selected_node)) selected_handle = handle;
                handles.push_back(std::move(handle));
            }
            _remove_treeitem(selected_handle);
        }

        m_candidates_typed.erase(m_candidates_typed.begin() + m_index);
        if (!m_candidates_typed.empty() &&
            static_cast<std::size_t>(m_index) >= m_candidates_typed.size())
            m_index = static_cast<::cw::lib::Integer>(m_candidates_typed.size() - 1);
        // Python と同様、削除後は新しいディレクトリー走査結果ではなく、表
        // 示中の一覧を意図的に保存する。 その順序と絞り込みの範囲を維持する。
        m_list.clear();
        for (const auto& candidate : m_candidates_typed) m_list.push_back(candidate_to_value(candidate));
        m_scenario_cache_typed[cache_key(m_nowdir_typed)] = m_candidates_typed;
        m_tree_items_ui.clear();
        m_tree_paths_ui.clear();
        _update_narrowcondition_impl();
        draw(true);
    } catch (...) {
        ::cw::util::print_ex(std::nullopt);
        scenario_select_play_sound("error");
        if (m_host_services) m_host_services->message("メッセージ", path + "の削除に失敗しました。");
    }
}

void ScenarioSelect::_remove_treeitem(std::shared_ptr<::cw::lib::Window> arg_item)
{
    const auto item = std::dynamic_pointer_cast<ScenarioTreeItemWindow>(arg_item);
    if (!item)
        throw std::invalid_argument("ScenarioSelect._remove_treeitem requires a valid tree item");
    if (!item->siblings) return;
    bool after_selected = false;
    for (const auto& weak : *item->siblings) {
        const auto sibling = weak.lock();
        if (!sibling) continue;
        if (sibling == item) { after_selected = true; continue; }
        // 負の ID は TreeCtrl の項目データを持たない仮要素に
        // 相当する。 Python と同様、それらの兄弟項目は変更しない。
        if (after_selected && sibling->id >= 0) --sibling->id;
    }
}

void ScenarioSelect::OnRenameBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (m_candidates_typed.empty() || m_index < 0 || static_cast<std::size_t>(m_index) >= m_candidates_typed.size() ||
        (arg_event && arg_event->title.empty())) return;
    if (std::holds_alternative<std::shared_ptr<FindResult>>(m_candidates_typed[static_cast<std::size_t>(m_index)])) return;
    const auto source = candidate_path(m_candidates_typed[static_cast<std::size_t>(m_index)]);
    if (source.empty()) return;
    if (!std::holds_alternative<::cw::lib::String>(m_nowdir_typed)) return;
    scenario_select_play_sound("click");
    const auto source_path = std::filesystem::u8path(source);
    const bool source_is_directory = ::cw::util::path_is_directory(source);
    const auto filename = path_text(source_path.filename());
    const auto extension = source_is_directory ? ::cw::lib::String{} : path_text(source_path.extension());
    const auto initial = extension.empty() ? filename : filename.substr(0, filename.size() - extension.size());
    ::cw::lib::String requested_name = arg_event ? arg_event->title : ::cw::lib::String{};
    if (requested_name.empty() && m_host_services) {
        const auto requested = m_host_services->request_text("名前を変更", initial);
        if (!requested) return;
        requested_name = *requested;
    }
    if (requested_name.empty()) return;
    const auto install_target = _get_installtarget();
    const auto destination_base = std::filesystem::u8path(std::get<::cw::lib::String>(m_nowdir_typed)) /
        std::filesystem::u8path(requested_name);
    auto destination = std::filesystem::u8path(path_text(destination_base) + extension);
    destination = std::filesystem::u8path(::cw::util::dupcheck_plus(path_text(destination_base), false, true) + extension);
    try {
        ::cw::util::move_path(source, path_text(destination));
        const bool destination_is_directory = ::cw::util::path_is_directory(path_text(destination));
        if (destination_is_directory && m_db_typed) m_db_typed->rename_dir(source, path_text(destination));
        if (m_db_typed) m_db_typed->update(std::get<::cw::lib::String>(m_nowdir_typed), current_skintype(), true, true);
        scenario_select_play_sound("harvest");
        rebuild_candidates();
        _select_installedpaths(path_text(destination), destination_is_directory ? ::cw::lib::String{} : std::get<1>(install_target), {});
    } catch (const std::exception&) {
        scenario_select_play_sound("error");
        if (m_host_services)
            m_host_services->message("メッセージ", source + "の名前の変更に失敗しました。");
    }
}

void ScenarioSelect::OnCreateLinkToScenario(std::shared_ptr<::cw::lib::Window> arg_event)
{
    scenario_select_play_sound("click");
    auto paths = event_paths(arg_event);
    if (paths.empty()) {
        request_document(DocumentAction::LinkScenario);
        return;
    }
    create_scenario_links(paths);
}

void ScenarioSelect::create_scenario_links(const std::vector<::cw::lib::String>& paths)
{
    if (paths.empty() || std::holds_alternative<std::shared_ptr<FindResult>>(m_nowdir_typed)) return;
    auto [headers, unused_files] = _to_headers(paths, true);
    (void)unused_files;
    // Py は初期値なしの reduce でヘッダーを平坦化するため
    // 、空のマップでは対象検索より前に TypeError となる。
    // ネイティブでは成功扱いせず、対応する型付きの引数例外を使う。
    if (headers.empty())
        throw std::invalid_argument("reduce() of empty iterable with no initial value");
    const bool has_headers = std::any_of(headers.begin(), headers.end(),
        [](const auto& entry) { return !entry.second.empty(); });
    if (!has_headers) return;
    scenario_select_play_sound("harvest");
    const auto target = _get_installtarget();
    auto target_dir = ::cw::util::get_linktarget(std::get<0>(target));
    if (target_dir.empty()) target_dir = std::get<0>(target);
    ::cw::lib::String first_link;
    for (const auto& [unused, bucket] : headers) {
        (void)unused;
        for (const auto& header : bucket) {
            if (!header) continue;
            auto link = path_text(std::filesystem::u8path(target_dir) / std::filesystem::u8path(basename_of(header->get_fpath()) + ".lnk"));
            ::cw::lib::Integer suffix = 2;
            while (std::filesystem::exists(std::filesystem::u8path(link))) {
                link = path_text(std::filesystem::u8path(target_dir) / std::filesystem::u8path(basename_of(header->get_fpath()) + "(" + std::to_string(suffix++) + ").lnk"));
            }
            ::cw::util::create_link(link, ::cw::util::get_linktarget(header->get_fpath()));
            if (first_link.empty()) first_link = link;
        }
    }
    if (!first_link.empty()) {
        _update_nowdir(std::get<0>(target), first_link);
    }
}

void ScenarioSelect::OnCreateLinkToDirectory(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (std::holds_alternative<std::shared_ptr<FindResult>>(m_nowdir_typed)) return;
    scenario_select_play_sound("click");
    auto paths = event_paths(arg_event);
    if (paths.empty()) {
        request_document(DocumentAction::LinkDirectory);
        return;
    }
    create_directory_link(paths.front());
}

void ScenarioSelect::create_directory_link(const ::cw::lib::String& path)
{
    if (path.empty() || std::holds_alternative<std::shared_ptr<FindResult>>(m_nowdir_typed)) return;
    const auto target = _get_installtarget();
    auto target_dir = ::cw::util::get_linktarget(std::get<0>(target));
    if (target_dir.empty()) target_dir = std::get<0>(target);
    auto source_dir = ::cw::util::get_linktarget(path);
    if (source_dir.empty()) source_dir = path;
    auto link = path_text(std::filesystem::u8path(target_dir) / std::filesystem::u8path(basename_of(source_dir) + ".lnk"));
    ::cw::lib::Integer suffix = 2;
    while (std::filesystem::exists(std::filesystem::u8path(link))) {
        link = path_text(std::filesystem::u8path(target_dir) / std::filesystem::u8path(basename_of(source_dir) + "(" + std::to_string(suffix++) + ").lnk"));
    }
    ::cw::util::create_link(link, source_dir);
    scenario_select_play_sound("harvest");
    _update_nowdir(std::get<0>(target), link);
}

void ScenarioSelect::_update_nowdir(::cw::lib::String arg_dpath, ::cw::lib::String arg_selection)
{
    if (arg_dpath.empty() || arg_selection.empty()) return;
    // リンク作成側は、相対または絶対の完全なパスを既に渡している。 Py と同
    // 様、そのまま転送する。dpath を前置すると相対パスの親が重複する。
    const auto path = arg_selection;
    (void)directory_candidates(ScenarioDirectory(arg_dpath), true);
    // Py と同様、先にディレクトリーを更新してから選択項目の祖先経
    // 路を保持する。 名前だけの経路では、入れ子フォルダー内でリンク
    // を作成した時にルートや FindResult へ飛んでしまう。
    _update_saveddirstack();
    auto [selected_names, selected_path] = get_selected();
    if (::cw::scenariodb::is_scenario(selected_path) && !selected_names.empty())
        selected_names.pop_back();
    selected_names.push_back(basename_of(path));
    set_selected(std::move(selected_names), path, true, true, std::vector<::cw::lib::Value>{});
}

std::tuple<::cw::dialog::scenarioinstall::HeaderBuckets, ::cw::dialog::scenarioinstall::FileBuckets> ScenarioSelect::_to_headers(std::vector<::cw::lib::String> arg_paths, bool arg_link)
{
    return ::cw::dialog::scenarioinstall::to_scenarioheaders(std::move(arg_paths), m_db_typed, current_skintype(), arg_link);
}

void ScenarioSelect::_show_selectedscenario(::cw::dialog::scenarioinstall::HeaderBuckets arg_headers)
{
    scenario_select_play_sound("equipment");
    m_search_text.clear();
    std::vector<::cw::lib::Value> values;
    for (const auto& [unused, headers] : arg_headers) { (void)unused; for (const auto& header : headers) if (header) values.emplace_back(std::static_pointer_cast<::cw::lib::Object>(header)); }
    const bool first = values.size() == 1;
    _set_findresult(std::move(values), first, true, -1);
}

void ScenarioSelect::_install_scenario(::cw::dialog::scenarioinstall::HeaderBuckets arg_headers, ::cw::dialog::scenarioinstall::HeaderBuckets arg_headers_with_link, ::cw::dialog::scenarioinstall::FileBuckets arg_notscenariofiles)
{
    if (arg_headers_with_link.empty()) return;
    const auto target = _get_installtarget();
    scenario_select_play_sound("signal");
    if (arg_headers.empty()) throw std::invalid_argument("install headers are empty");
    auto destination = ::cw::util::get_linktarget(std::get<0>(target));
    if (destination.empty()) destination = std::get<0>(target);
    std::size_t scenario_count = 0;
    for (const auto& [unused, headers] : arg_headers) { (void)unused; scenario_count += headers.size(); }
    std::shared_ptr<::cw::header::ScenarioHeader> first_header;
    for (const auto& [unused, headers] : arg_headers) {
        (void)unused;
        if (!headers.empty() && headers.front()) {
            first_header = headers.front();
            break;
        }
    }
    ::cw::lib::String display_name;
    if (scenario_count == 1 && first_header) {
        display_name = value_string(first_header->m_name);
        const auto author = value_string(first_header->m_author);
        if (!author.empty()) display_name += "(" + author + ")";
        display_name = "「" + display_name + "」";
    } else {
        display_name = std::to_string(scenario_count) + "本のシナリオ";
    }
    if (!first_header) throw std::out_of_range("install header sequence is empty");
    auto directory_name=basename_of(std::get<0>(target));
    if (::cw::util::supports_shell_links() && lower_ascii(directory_name).ends_with(".lnk")) directory_name.resize(directory_name.size()-4);
    const auto prompt = display_name + "を" + directory_name + "にインストールしますか？";
    std::vector<std::shared_ptr<::cw::header::ScenarioHeader>> headers_sequence;
    for (const auto& [key,headers]:arg_headers) headers_sequence.insert(headers_sequence.end(),headers.begin(),headers.end());
    const auto description=::cw::dialog::scenarioinstall::create_installdesc(headers_sequence);
    const auto view_prompt = display_name + "を検索結果として表示します。";
    if (m_host_services) {
        const auto choice = m_host_services->choose_install_with_detail(::cw::dialog::select::select_msg("message","メッセージ"),prompt,view_prompt,description);
        if (choice == ScenarioInstallChoice::cancel) return;
        if (choice == ScenarioInstallChoice::view) {
            _show_selectedscenario(std::move(arg_headers_with_link));
            return;
        }
    }
    m_processing_typed = true;
    struct ResetProcessing { bool& value; ~ResetProcessing() { value=false; } } reset_processing{m_processing_typed};
    sync_ui();
    {
        const auto result = ::cw::dialog::scenarioinstall::install_scenario(nullptr, std::move(arg_headers),
                                                                               std::move(arg_notscenariofiles), m_scedir_typed,
                                                                               destination, m_db_typed, current_skintype());
        const auto& paths = std::get<1>(result);
        if (!paths.empty()) {
            scenario_select_play_sound("harvest");
            // Py と同様、編集コールバックを抑止しながら検索文字列を消
            // し、 他の項目が失敗していても完了済みのパスを選択する。
            m_search_text.clear();
            sync_search_input();
            m_processing_typed = false;
            _select_installedpaths(paths.front(), std::get<1>(target), paths);
        }
    }m_processing_typed = false;
    sync_ui();
}

void ScenarioSelect::OnClickInfoBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    scenario_select_play_sound("click");
    auto parent=std::make_shared<::cw::lib::Window>();
    parent->native_handle=m_parent_native_handle;
    (void)::cw::dialog::text::show_common_readme(
        std::move(parent),::cw::dialog::select::select_msg("description", "解説"),m_texts,
        [this](bool arg_right) {
            change_page(arg_right ? 1 : -1);
        },
        [this] { return static_cast<::cw::lib::Integer>(m_candidates_typed.size()); },
        [this] { return get_texts(); });
    // 既定ホストの show_readme も、この同じ共通の表示処理
    // を呼ぶ。 モーダルが失敗・終了しても、親やシナリオ移動のコール
    // バックを外して再度開かない。一回のクリックにつき一度だけ試す。
    request_dialog_presentation_refresh();
}

void ScenarioSelect::OnClickConvBtn(std::shared_ptr<::cw::lib::Window> arg_evt)
{
    if (m_processing_typed || m_finished_typed) return;
    ::cw::lib::String path = arg_evt ? arg_evt->title : ::cw::lib::String{};
    if (path.empty()) request_document(DocumentAction::Convert);
    else conv_scenario(std::move(path));
}

void ScenarioSelect::OnClickYesBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (m_candidates_typed.empty() || m_index < 0 || static_cast<std::size_t>(m_index) >= m_candidates_typed.size()) return;
    const auto& selected = m_candidates_typed[static_cast<std::size_t>(m_index)];
#if defined(CARDWIRTH_LOG_ENABLED)
    log_scenarioselect("confirm index=" + std::to_string(m_index) +
                       " candidates=" + std::to_string(m_candidates_typed.size()) +
                       " can_decide=" + (can_decide() ? "1" : "0") +
                       " path=" + candidate_path(selected));
#endif
    if (is_scenario_candidate(selected)) {
        // ダブルクリックや張り紙の実行にも、明示的な「決定
        // 」ボタンと同じ終了印・称号・表示条件を適用する。
        if (!can_decide()) return;
        scenario_select_play_sound("signal");
        OnOk(std::make_shared<::cw::lib::Window>());
    }
    else if (std::holds_alternative<std::shared_ptr<FindResult>>(selected)) {
        scenario_select_play_sound("equipment");
        auto result = std::get<std::shared_ptr<FindResult>>(selected);
        if (!result) return;
        m_dirstack_typed.emplace_back(m_nowdir_typed, "/find_result");
        m_nowdir_typed = result;
        load_directory(m_nowdir_typed, false);
        m_index = 0;
        _update_saveddirstack();
        enable_btn();
        draw(true);
    }
    else {
        scenario_select_play_sound("equipment");
        m_dirstack_typed.emplace_back(m_nowdir_typed, candidate_name(selected));
        m_nowdir_typed = ::cw::util::get_linktarget(candidate_path(selected));
        if (std::get_if<::cw::lib::String>(&m_nowdir_typed) && std::get<::cw::lib::String>(m_nowdir_typed).empty())
            m_nowdir_typed = candidate_path(selected);
        load_directory(m_nowdir_typed, false);
        m_index = 0;
        _update_saveddirstack();
        enable_btn();
        draw(true);
    }
}

void ScenarioSelect::BackPaper()
{
    scenario_select_play_sound("equipment");
    if (m_dirstack_typed.empty()) throw std::out_of_range("scenario directory stack is empty");
    const auto selected_name = std::get<1>(m_dirstack_typed.back());
    m_nowdir_typed = std::get<0>(m_dirstack_typed.back());
    m_dirstack_typed.pop_back();
    load_directory(m_nowdir_typed, false);
    m_index = 0;
    if (!selected_name.empty() && selected_name.front() != '/') {
        for (std::size_t i = 0; i < m_candidates_typed.size(); ++i) {
            if (!std::holds_alternative<::cw::lib::String>(m_candidates_typed[i])) continue;
            const auto candidate = basename_of(std::get<::cw::lib::String>(m_candidates_typed[i]));
            if (lower_ascii(candidate) == lower_ascii(selected_name)) {
                m_index = static_cast<::cw::lib::Integer>(i);
            }
        }
    }
    _update_saveddirstack();
    enable_btn();
    draw(true);
}

// 共通のキャンセル処理が、表示された戻るラベルに基づく判断を行う。この互換入
// 口は型付きのツリー専用状態と dirstack を使い、 別のホストボタン
// へ ProcessEvent を送らず、最終的なキャンセル処理へ委ねる。
void ScenarioSelect::OnClickNoBtn(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (m_tree.is_none() && !m_dirstack_typed.empty()) {
        BackPaper(); return;
    }
    OnCancel2({});
}

void ScenarioSelect::OnClickViewBtn(::cw::lib::Value arg_event)
{
    (void)arg_event;
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_show_paperandtree) return;
    scenario_select_play_sound("equipment");
    if (m_tree.is_none()) {
        show_tree(false);
        m_tree_ensure_selection=true;
        m_presentation_search_focus=false;
        m_presentation_button_focus=-1;
        m_presentation_auxiliary_focus=-2;
        if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) ::cw::g_cwpy->m_setting->m_show_scenariotree = true;
    } else {
        m_tree = ::cw::lib::Value{};
        m_presentation_auxiliary_focus = -1;
        if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) ::cw::g_cwpy->m_setting->m_show_scenariotree = false;
        _update_narrowcondition_impl();
        draw(true);
    }
    update_additionals();
    _do_layout();
    request_dialog_presentation_refresh();
    enable_btn();
}

bool ScenarioSelect::_can_opendir()
{
    return !m_candidates_typed.empty() && m_index >= 0 && static_cast<std::size_t>(m_index) < m_candidates_typed.size() &&
           !std::holds_alternative<std::shared_ptr<FindResult>>(m_candidates_typed[static_cast<std::size_t>(m_index)]);
}

bool ScenarioSelect::_can_editor()
{
    if (!::cw::g_cwpy || !::cw::g_cwpy->m_setting ||
        ::cw::g_cwpy->m_setting->m_editor.empty() || !_can_opendir()) return false;
    const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(
        &m_candidates_typed[static_cast<std::size_t>(m_index)]);
    return header && *header;
}

void ScenarioSelect::open_directory()
{
    if (!_can_opendir()) return;
    scenario_select_play_sound("click");
    const auto& candidate = m_candidates_typed[static_cast<std::size_t>(m_index)];
    auto target = ::cw::util::get_linktarget(candidate_path(candidate));
    if (target.empty()) return;
    std::error_code ec;
    target = path_text(std::filesystem::absolute(std::filesystem::u8path(target), ec));
    bool file_target = std::filesystem::is_regular_file(std::filesystem::u8path(target), ec);
    if (file_target) {
        const auto& filer = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::g_cwpy->m_setting->m_filer_file : ::cw::lib::String{};
        if (!launch_windows_path(filer, target, filer.empty())) {
            scenario_select_play_sound("error");
            m_detailtext_typed = "ファイルを開けません: " + target;
            if (m_host_services) m_host_services->message("メッセージ",m_detailtext_typed);
        }
        return;
    }
    if (is_scenario_candidate(candidate)) {
        const auto summary_wsm = std::filesystem::u8path(target) / "Summary.wsm";
        const auto summary_xml = std::filesystem::u8path(target) / "Summary.xml";
        if (std::filesystem::is_regular_file(summary_wsm, ec)) {
            target = path_text(summary_wsm);
            file_target = true;
        } else if (std::filesystem::is_regular_file(summary_xml, ec)) {
            target = path_text(summary_xml);
            file_target = true;
        }
    }
    if (file_target) {
        const auto& filer = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::g_cwpy->m_setting->m_filer_file : ::cw::lib::String{};
        if (!launch_windows_path(filer, target, filer.empty())) {
            scenario_select_play_sound("error");
            m_detailtext_typed = "ファイルを開けません: " + target;
        }
        return;
    }
    const auto& filer = ::cw::g_cwpy && ::cw::g_cwpy->m_setting ? ::cw::g_cwpy->m_setting->m_filer_dir : ::cw::lib::String{};
    if (!launch_windows_path(filer, target, false)) {
        scenario_select_play_sound("error");
        m_detailtext_typed = "フォルダを開けません: " + target;
        if (m_host_services) m_host_services->message("メッセージ",m_detailtext_typed);
    }
}

void ScenarioSelect::open_with_editor()
{
    if (!_can_editor()) return;
    scenario_select_play_sound("click");
    const auto& setting = ::cw::g_cwpy ? ::cw::g_cwpy->m_setting : nullptr;
    if (!setting || setting->m_editor.empty()) return;
    const auto& candidate = m_candidates_typed[static_cast<std::size_t>(m_index)];
    auto target = ::cw::util::get_linktarget(candidate_path(candidate));
    if (target.empty()) return;
    std::error_code ec;
    target = path_text(std::filesystem::absolute(std::filesystem::u8path(target), ec));
    if (std::filesystem::is_directory(std::filesystem::u8path(target), ec)) {
        const auto summary = std::filesystem::u8path(target) / "Summary.wsm";
        if (std::filesystem::is_regular_file(summary, ec)) target = path_text(summary);
    }
    if (!launch_windows_path(setting->m_editor, target, false)) {
        m_detailtext_typed = "エディタを起動できません: " + setting->m_editor;
        if (m_host_services) m_host_services->message("メッセージ",m_detailtext_typed);
    }
}

void ScenarioSelect::convert_scenario()
{
    if (m_candidates_typed.empty() || m_index < 0 ||
        static_cast<std::size_t>(m_index) >= m_candidates_typed.size()) return;
    const auto& candidate = m_candidates_typed[static_cast<std::size_t>(m_index)];
    const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&candidate);
    if (!header || !*header || value_integer((*header)->m_type) != ::cw::scenariodb::g_TYPE_CLASSIC) return;
    const auto path = ::cw::util::get_linktarget(candidate_path(candidate));
    if (!path.empty()) conv_scenario(path);
}

void ScenarioSelect::OnSelect(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (can_clickcenter()) OnClickYesBtn(std::move(arg_event));
}

// Py は「いいえ」のボタン・ラベルを経由する。このネイティブの直
// 接入口は、張り紙とツリーの戻る操作または最終キャンセルを処理する
// 。 共通の Cancel/Escape は別途、戻るラベルによる
// 移動を管理するため、ここで別のホストボタンイベントを合成しない。
void ScenarioSelect::OnCancel(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (!(m_tree.is_none() && !m_dirstack_typed.empty())) scenario_select_play_sound("click");
    const bool paper_and_tree=::cw::g_cwpy && ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_show_paperandtree;
    if (!m_dirstack_typed.empty() && paper_and_tree) BackPaper();
    else OnClickNoBtn(nullptr);
}

void ScenarioSelect::OnDestroy(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    m_search_input.retire();
    cancel_document_request();
    m_finished_typed = true;
    _stop_poster_animation();
}

void ScenarioSelect::OnPosterAnimate(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
    if (m__poster_anim_stopped || m__quit) return;
    bool changed = false;
    for (auto& [key, animation] : m__poster_animations) {
        (void)key;
        auto& [path, instance_id, frame_id] = animation;
        const auto [bitmap, current_frame] = ::cw::animatedimage::get_wxbmp(path, instance_id);
        if (bitmap && *bitmap && current_frame != frame_id) {
            frame_id = current_frame;
            changed = true;
        }
    }
    if (changed) {
        sync_ui();
        request_dialog_presentation_refresh();
    }
}

void ScenarioSelect::_sync_poster_animation(std::optional<std::shared_ptr<::cw::header::ScenarioHeader>> arg_header)
{
    std::shared_ptr<::cw::header::ScenarioHeader> previous;
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m__poster_anim_header.storage()); object && *object)
        previous = std::dynamic_pointer_cast<::cw::header::ScenarioHeader>(*object);
    if (previous == (arg_header ? *arg_header : nullptr)) {
        const bool alive = !m__poster_animations.empty() && std::all_of(
            m__poster_animations.begin(), m__poster_animations.end(), [](const auto& item) {
                const auto& [path, instance_id, frame_id] = item.second;
                (void)frame_id;
                return ::cw::animatedimage::has_instance(path, instance_id);
            });
        if (alive) return;
    }
    _stop_poster_animation();
    m__poster_anim_header = arg_header && *arg_header ? ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(*arg_header)) : ::cw::lib::Value{};
    if (!arg_header || !*arg_header) return;
    if (m__poster_anim_owner.empty()) {
        std::ostringstream owner;
        owner << "ScenarioSelectPoster:" << reinterpret_cast<std::uintptr_t>(this);
        m__poster_anim_owner = owner.str();
    }
    const auto images_it = (*arg_header)->m_images.find(1);
    if (images_it == (*arg_header)->m_images.end()) return;
    const auto count = (std::min)(images_it->second.size(), (*arg_header)->m_imgpaths.size());
    for (std::size_t index = 0; index < count; ++index) {
        if (!images_it->second[index] || images_it->second[index]->empty()) continue;
        std::shared_ptr<::cw::image::ImageInfo> info;
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&(*arg_header)->m_imgpaths[index].storage()); object && *object)
            info = std::dynamic_pointer_cast<::cw::image::ImageInfo>(*object);
        const auto info_path = info ? info->m_path : ::cw::lib::String{};
        const auto extension = ::cw::animatedimage::get_supported_extension(info_path, images_it->second[index]);
        if (extension.empty()) continue;
        const auto source_name = ::cw::animatedimage::is_supported_path(info_path)
                                     ? info_path : "poster" + extension;
        const auto path = (*arg_header)->get_fpath() + "::" + std::to_string(index) + "::" + source_name;
        const auto instance_id = ::cw::animatedimage::acquire(path, m__poster_anim_owner, false, images_it->second[index]);
        if (!instance_id) continue;
        // get_wxbmps() が返す ImageInfo ラッパーは、CardHeader::m_imgpaths
        // と同じポインターとは限らない。 Python
        // と同じ安定した一覧の位置でフレームを対応付ける。
        const auto key = static_cast<::cw::lib::Integer>(index);
        m__poster_animations[key] = {path, *instance_id, 0};
    }
    m__poster_anim_stopped = m__poster_animations.empty();
}

void ScenarioSelect::_stop_poster_animation()
{
    m__poster_anim_stopped = true;
    if (!m__poster_anim_owner.empty()) ::cw::animatedimage::release(m__poster_anim_owner);
    m__poster_animations.clear();
    m__poster_anim_header = {};
}

void ScenarioSelect::_on_narrowcondition()
{
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) {
        ::cw::g_cwpy->m_setting->m_scenario_narrowtype = m_narrow_type_typed;
        ::cw::g_cwpy->m_setting->m_scenario_sorttype = m_sort_type_typed;
    }
    update_narrowcondition();
}

void ScenarioSelect::draw(bool arg_update)
{
    _draw_impl(arg_update);
    sync_ui();
    request_dialog_presentation_refresh();
}

void ScenarioSelect::_update_pagelabel()
{
    m_pagelabel = ::cw::lib::Value(std::to_string(m_candidates_typed.empty() ? 1 : m_index + 1) + "/" +
                                   std::to_string(m_candidates_typed.empty() ? 1 : m_candidates_typed.size()));
}

std::shared_ptr<::cw::lib::Bitmap> ScenarioSelect::_get_bg()
{
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m__bg.storage()); object && *object) return std::dynamic_pointer_cast<::cw::lib::Bitmap>(*object);
    const auto skindir = ::cw::g_cwpy ? value_string(::cw::g_cwpy->m_skindir) : ::cw::lib::String{};
    const auto resource = ::cw::util::find_resource(
        path_text(std::filesystem::u8path(skindir) / "Table" / "Bill"), ::cw::g_M_IMG);
    auto bitmap = ::cw::util::load_wxbmp(resource, false, nullptr, {}, std::nullopt, true, true, false, std::nullopt);
    if (!bitmap) bitmap = ::cw::util::load_wxbmp_masked_empty_bitmap();
    m__bg = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(bitmap));
    return bitmap;
}

std::shared_ptr<::cw::lib::Bitmap> ScenarioSelect::_get_bg_scaled()
{
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&m__bg_scaled.storage()); object && *object) return std::dynamic_pointer_cast<::cw::lib::Bitmap>(*object);
    auto bitmap = _get_bg();
    const auto scaled_value = ::cw::wins(::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(bitmap)));
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&scaled_value.storage()); object && *object)
        if (auto scaled = std::dynamic_pointer_cast<::cw::lib::Bitmap>(*object)) bitmap = std::move(scaled);
    m__bg_scaled = ::cw::lib::Value(std::static_pointer_cast<::cw::lib::Object>(bitmap));
    return bitmap;
}

::cw::lib::String ScenarioSelect::get_detailtext()
{
    const bool paper_visible = m_tree.is_none() ||
                               (::cw::g_cwpy && ::cw::g_cwpy->m_setting &&
                                ::cw::g_cwpy->m_setting->m_show_paperandtree);
    const bool tree_visible = !m_tree.is_none();
    std::vector<::cw::lib::String> sections;
    if (paper_visible) {
        const auto paper = _get_paperdetailtext();
        if (!paper.empty()) sections.push_back(paper);
    }
    if (tree_visible) {
        const auto tree = _get_treedetailtext();
        if (!tree.empty()) sections.push_back(tree);
    }
    if (sections.empty()) return {};
    ::cw::lib::String result = sections.front();
    if (sections.size() > 1) result += "\n--------------------------------------\n" + sections[1];
    if (result.empty() || result.back() != '\n') result.push_back('\n');
    return result;
}

::cw::lib::String ScenarioSelect::_get_paperdetailtext()
{
    if (m_candidates_typed.empty() || m_index < 0 ||
        static_cast<std::size_t>(m_index) >= m_candidates_typed.size()) return {};
    const auto& selected = m_candidates_typed[static_cast<std::size_t>(m_index)];
    if (const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&selected);
        header && *header) {
        auto result = ::cw::sprite::bill::get_detailtext(*header);
        if (!result.empty() && result.back() != '\n') result.push_back('\n');
        return result;
    }

    std::vector<::cw::lib::String> lines;
    auto selected_name = std::holds_alternative<std::shared_ptr<FindResult>>(selected)
                             ? ::cw::dialog::select::select_msg("find_result", "検索結果")
                             : candidate_name(selected);
    auto title = "[ " + selected_name + " ]";
    const auto title_width = ::cw::util::get_strlen(title);
    if (title_width < 38) title += ::cw::lib::String(static_cast<std::size_t>(38 - title_width), '-');
    lines.push_back(std::move(title));
    std::vector<ScenarioCandidate> contents;
    if (const auto* find = std::get_if<std::shared_ptr<FindResult>>(&selected); find && *find) {
        contents=findresult_candidates(**find);
        sort_candidates(contents);
    } else {
        auto directory = ::cw::util::get_linktarget(candidate_path(selected));
        if (directory.empty()) directory = candidate_path(selected);
        if (::cw::util::path_is_directory(directory))
            contents = directory_candidates(ScenarioDirectory(directory), true);
    }
    for (const auto& candidate : contents) {
        ::cw::lib::String name;
        ::cw::lib::String addition;
        if (const auto* item = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&candidate);
            item && *item) {
            name = value_string((*item)->m_name);
            if (m_sort_type_typed == 2) {
                if (!value_string((*item)->m_author).empty())
                    addition = "(" + value_string((*item)->m_author) + ")";
            }
            else if (m_sort_type_typed == 4)
                addition = "[" + _formatted_mtime(value_real((*item)->m_mtime), false) + "]";
            else {
                const auto min_level = value_integer((*item)->m_levelmin);
                const auto max_level = value_integer((*item)->m_levelmax);
                if (min_level || max_level) {
                    const auto min_label = min_level ? std::to_string(min_level) : " ";
                    const auto max_label = max_level ? std::to_string(max_level) : " ";
                    addition = min_label == max_label
                                   ? "[" + min_label + "]"
                                   : "[" + min_label + "～" + max_label + "]";
                }
            }
        } else {
            name = "[" + candidate_name(candidate) + "]";
        }
        if (!addition.empty()) name += " " + addition;
        lines.push_back(std::move(name));
    }
    ::cw::lib::String result;
    for (const auto& line : lines) {
        if (!result.empty()) result.push_back('\n');
        result += line;
    }
    if (!result.empty() && result.back() != '\n') result.push_back('\n');
    return result;
}

::cw::lib::String ScenarioSelect::_get_treedetailtext()
{
    if (m_tree.is_none() || m_candidates_typed.empty()) return {};
    ScenarioSelectUiState tree_state;
    populate_tree_ui_state(tree_state);
    std::vector<::cw::lib::String> lines;
    auto root = basename_of(m_scedir_typed);
    if (root.size() >= 4 && lower_ascii(root.substr(root.size() - 4)) == ".lnk") root.resize(root.size() - 4);
    lines.push_back("[" + root + "]");
    const auto append_children = [&](auto&& self, ::cw::lib::Integer parent, const ::cw::lib::String& indent) -> void {
        std::vector<std::size_t> children;
        for (std::size_t index = 0; index < tree_state.tree_nodes.size(); ++index)
            if (tree_state.tree_nodes[index].parent_index == parent) children.push_back(index);
        for (std::size_t child_index = 0; child_index < children.size(); ++child_index) {
            const auto index = children[child_index];
            const auto& node = tree_state.tree_nodes[index];
            const bool last = child_index + 1 == children.size();
            auto label = node.label;
            if (node.icon_index == 4 || node.icon_index == 5) label = "[" + label + "]";
            lines.push_back(indent + (last ? "└" : "├") + label);
            if (!node.placeholder)
                self(self, static_cast<::cw::lib::Integer>(index),
                     indent + (last ? "   " : "│ "));
        }
    };
    append_children(append_children, -1, " ");
    ::cw::lib::String result;
    for (const auto& line : lines) {
        if (!result.empty()) result.push_back('\n');
        result += line;
    }
    return result;
}

void ScenarioSelect::_draw_impl(bool arg_update)
{
    const bool paper_visible = m_tree.is_none() ||
        (::cw::g_cwpy && ::cw::g_cwpy->m_setting &&
         ::cw::g_cwpy->m_setting->m_show_paperandtree);
    if (!m_candidates_typed.empty() && m_index >= 0 && static_cast<std::size_t>(m_index) < m_candidates_typed.size()) {
        const auto& selected = m_candidates_typed[static_cast<std::size_t>(m_index)];
        if (paper_visible) {
            if (const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&selected); header && *header)
                _sync_poster_animation(*header);
            else
                _sync_poster_animation(std::nullopt);
        } else {
            // Python と同様、ツリー専用モードで上部パネルを隠したら、張り紙の
            // アニメーション所有権を解放する。 見えない張り紙の定期更新は行わない。
            _sync_poster_animation(std::nullopt);
        }
        if (!arg_update) m_texts = get_texts();
    } else {
        _sync_poster_animation(std::nullopt);
        m_texts.clear();
    }
    if (arg_update) {
        // Py と同様、張り紙を先に同期してからラベル・ボタンを更新する。 変
        // 換処理や draw(True) の直接呼び出しでも同じ更新を行う。
        _update_pagelabel();
        enable_btn();
    }
    m_detailtext_typed = get_detailtext();
    sync_ui();
}

void ScenarioSelect::_enable_btn2(::cw::lib::Value arg_header, std::optional<std::shared_ptr<::cw::lib::DeviceContext>> arg_dc)
{
    (void)arg_dc;
    m__imgidx_playing = false;
    m__imgidx_complete = false;
    m__imgidx_invisible = false;
    if (auto object = std::get_if<::cw::lib::ObjectPtr>(&arg_header.storage()); object && *object) {
        if (auto header = std::dynamic_pointer_cast<::cw::header::ScenarioHeader>(*object)) {
            // Py と同様、この順序で最初に一致した印だけを表示する。
            m__imgidx_playing = is_playing(header);
            if (!value_bool(m__imgidx_playing)) {
                m__imgidx_complete = is_complete(header);
                if (!value_bool(m__imgidx_complete)) m__imgidx_invisible = is_invisible(header);
            }
        }
    }
}

bool ScenarioSelect::is_playing(std::shared_ptr<::cw::header::ScenarioHeader> arg_header)
{
    if (!arg_header) return false;
    const auto target=::cw::util::get_linktarget(arg_header->get_fpath());
    return m_nowplaying_typed.contains(::cw::util::get_keypath(target));
}

bool ScenarioSelect::is_complete(std::shared_ptr<::cw::header::ScenarioHeader> arg_header) const
{
    return arg_header && m_stamps_typed.contains(value_string(arg_header->m_name));
}

bool ScenarioSelect::is_invisible(std::shared_ptr<::cw::header::ScenarioHeader> arg_header) const
{
    if (!arg_header) return false;
    const auto coupons = value_string(arg_header->m_coupons);
    if (coupons.empty()) return false;
    ::cw::lib::Integer found = 0;
    for (const auto& coupon : ::cw::lib::encoding::splitlines(coupons)) {
        if (!coupon.empty()) {
            const auto it = m_coupons_typed.find(coupon);
            if (it != m_coupons_typed.end()) found += (std::min)(::cw::lib::Integer{1}, it->second);
        }
    }
    return found < value_integer(arg_header->m_couponsnum);
}

void ScenarioSelect::update_narrowcondition()
{
    if (!_update_narrowparams()) return;
    _update_narrowcondition_impl();
}

void ScenarioSelect::_update_narrowcondition_impl()
{
    for (auto& [key,candidates] : m_scenario_cache_typed) {
        candidates.erase(std::remove_if(candidates.begin(),candidates.end(),[](const ScenarioCandidate& candidate) {
            const auto* path=std::get_if<::cw::lib::String>(&candidate);
            return path && !::cw::util::path_exists(*path);
        }),candidates.end());
    }
    // コントロール・メニュー操作・コールバックで、絞り込みと選択の経路を共通化する。
    rebuild_candidates(false);
}

std::tuple<std::vector<std::shared_ptr<::cw::lib::Window>>, std::vector<::cw::lib::String>> ScenarioSelect::create_treeitems(std::shared_ptr<::cw::lib::Window> arg_treeitem, bool arg_freeze)
{
    // 置き換え用のモデルを完全に構築してから公開する。 wx.TreeCtrl.Freeze/Thaw
    // に相当する不可分の更新とし、一部だけ埋まっ
    // たツリーへ選択イベントが届かないようにする。
    (void)arg_freeze;
    std::vector<std::shared_ptr<::cw::lib::Window>> items;
    std::vector<::cw::lib::String> paths;
    std::vector<::cw::lib::String> ui_items;
    std::vector<::cw::lib::String> ui_paths;
    ScenarioDirectory parent = m_nowdir_typed;
    if (arg_treeitem && !arg_treeitem->title.empty()) parent = arg_treeitem->title;
    const auto candidates = directory_candidates(parent, false);
    const auto siblings = std::make_shared<ScenarioTreeItemWindow::Siblings>();
    for (const auto& candidate : candidates) {
        if (!candidate_is_showing(candidate)) continue;
        auto item = make_tree_item(arg_treeitem, siblings);
        item->title = candidate_name(candidate);
        item->id = static_cast<::cw::lib::Integer>(items.size());
        items.push_back(item);
        const auto path = std::holds_alternative<std::shared_ptr<FindResult>>(candidate)
            ? ::cw::lib::String("/find_result") : candidate_path(candidate);
        ui_items.push_back(item->title);
        ui_paths.push_back(path);
        if (!is_scenario_candidate(candidate)) paths.push_back(path);
    }
    m_tree_items_ui = std::move(ui_items);
    m_tree_paths_ui = std::move(ui_paths);
    return {std::move(items), std::move(paths)};
}

std::shared_ptr<::cw::lib::Window> ScenarioSelect::_create_findresultitem(::cw::lib::Integer arg_index, std::shared_ptr<::cw::lib::Window> arg_treeitem, std::shared_ptr<::cw::dialog::scenarioselect::FindResult> arg_findresult)
{
    auto item = make_tree_item(arg_treeitem);
    item->id = arg_index;
    item->title = ::cw::dialog::select::select_msg("find_result", "検索結果");
    if (arg_treeitem) item->bounds = arg_treeitem->bounds;
    // ネイティブのツリーハンドルは共通のツリー状態を反映する。 空の結果を示す子は
    // populate_tree_ui_state が生成し、別のツリーは作らない。
    if (arg_findresult) m_find_result_typed = arg_findresult;
    return item;
}

::cw::lib::String ScenarioSelect::_formatted_mtime(::cw::lib::Real arg_mtime, bool arg_showtime)
{
    const auto time = static_cast<std::time_t>(arg_mtime);
    std::tm tm{};
#ifdef _WIN32
    localtime_s(&tm, &time);
#else
    localtime_r(&time, &tm);
#endif
    std::ostringstream stream;
    stream << std::put_time(&tm, arg_showtime ? "%Y-%m-%d %H:%M" : "%Y-%m-%d");
    return stream.str();
}

std::shared_ptr<::cw::lib::Window> ScenarioSelect::create_treeitem(::cw::lib::Integer arg_index, std::shared_ptr<::cw::lib::Window> arg_treeitem, std::shared_ptr<::cw::header::ScenarioHeader> arg_header)
{
    auto item = make_tree_item(arg_treeitem);
    item->id = arg_index;
    if (arg_header) {
        item->title = value_string(arg_header->m_name);
        if (m_sort_type_typed == 0 &&
            (value_integer(arg_header->m_levelmin) != 0 || value_integer(arg_header->m_levelmax) != 0)) {
            const auto min_level = value_integer(arg_header->m_levelmin);
            const auto max_level = value_integer(arg_header->m_levelmax);
            // Py の %2d / %2s と同様、空の端点も含め
            // 最小幅を二文字とする。 桁数の多い値は切り詰めない。
            const auto level_field = [](const ::cw::lib::String& text) {
                return text.size() < 2 ? ::cw::lib::String(2 - text.size(), ' ') + text : text;
            };
            if (min_level == max_level)
                item->title = "[    " + level_field(std::to_string(min_level)) + "] " + item->title;
            else
                item->title = "[" + level_field(min_level ? std::to_string(min_level) : "") + "～" +
                               level_field(max_level ? std::to_string(max_level) : "") + "] " + item->title;
        }
        if (m_sort_type_typed == 4) item->title += " (" + _formatted_mtime(value_real(arg_header->m_mtime), true) + ")";
        else if (m_sort_type_typed == 3) {
            auto filename = value_string(arg_header->m_fname);
            if (::cw::util::supports_shell_links() && filename.size() >= 4 &&
                lower_string(filename.substr(filename.size() - 4)) == ".lnk")
                filename.resize(filename.size() - 4);
            item->title += " (" + filename + ")";
        }
        else if (m_sort_type_typed == 2 && !value_string(arg_header->m_author).empty()) item->title += " (" + value_string(arg_header->m_author) + ")";
    }
    if (arg_treeitem) item->bounds = arg_treeitem->bounds;
    return item;
}

void ScenarioSelect::show_tree(bool arg_freeze)
{
    // create_treeitems中もwx版と同じく検索欄を非表示扱いにする。
    m_tree = ::cw::lib::Value(std::make_shared<::cw::lib::Object>());
    const auto created = create_treeitems(std::make_shared<::cw::lib::Window>(), arg_freeze);
    (void)created;
    sync_ui();
    request_dialog_presentation_refresh();
}

void ScenarioSelect::OnTreeItemExpanded(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (arg_event) _expand_tree(arg_event);
}

void ScenarioSelect::_expand_tree(std::shared_ptr<::cw::lib::Window> arg_selitem)
{
    if (!arg_selitem || arg_selitem->title.empty()) return;
    _expandeditem(arg_selitem, arg_selitem->title, {});
}

bool ScenarioSelect::is_tree_visible() const
{
    return !m_tree.is_none() || (::cw::g_cwpy && ::cw::g_cwpy->m_setting &&
        ::cw::g_cwpy->m_setting->m_show_paperandtree);
}

void ScenarioSelect::_expandeditem(std::shared_ptr<::cw::lib::Window> arg_selitem, ::cw::lib::String arg_startdir, std::set<::cw::lib::String> arg_expandedset)
{
    if (!arg_selitem || m_processing_typed || !is_tree_visible() || arg_selitem->title.empty() ||
        arg_selitem->title=="/find_result") return;
    const auto dpath=arg_selitem->title;
    const auto key=cache_key(ScenarioDirectory(dpath));
    if ((m_expanded_tree_paths.contains(key) && m_scenario_cache_typed.contains(key)) ||
        !arg_expandedset.insert(key).second) return;
    if (m_updatenames_thr && *m_updatenames_thr) (*m_updatenames_thr)->m_quit=true;
    m_updatenames_thr.reset();
    if (const auto current=std::get_if<::cw::lib::String>(&m_nowdir_typed);current && *current==dpath) {
        m_names={::cw::lib::Value(::cw::dialog::select::select_msg("now_loading","読込中..."))};
        m__gray_idx=0;
    }
    auto worker=std::make_shared<UpdateNamesThread>();
    auto parents=get_dirstack(arg_selitem);
    if (!parents.empty()) parents.pop_back();
    worker->initialize(shared_from_this(),dpath,dpath,parents,arg_startdir,arg_expandedset,current_skintype());
    m_updatenames_thr=worker;
    m_loading_tree_paths.insert(key);
    m_expanded_tree_paths.insert(key);
    std::thread([worker] { try { worker->run(); } catch (...) { ::cw::util::print_ex(std::nullopt); } }).detach();
    request_dialog_presentation_refresh();
}

void ScenarioSelect::OnTreeItemCollapsed(std::shared_ptr<::cw::lib::Window> arg_event)
{
    if (arg_event) _collapse_tree(arg_event);
}

void ScenarioSelect::_collapse_tree(std::shared_ptr<::cw::lib::Window> arg_item)
{
    if (!arg_item || arg_item->title.empty()) return;
    ScenarioSelectUiState state;
    populate_tree_ui_state(state);
    // 選択行の祖先を折り畳む場合は、TreeCtrl と同様に先にそ
    // の祖先を選ぶ。 隠れる子をアクティブなシナリオのまま残さない。
    for (auto i = state.tree_selected_node_index; i >= 0;
         i = state.tree_nodes[static_cast<std::size_t>(i)].parent_index) {
        if (state.tree_nodes[static_cast<std::size_t>(i)].path == arg_item->title) {
            (void)select_tree_node(i,false);
            break;
        }
    }
    ScenarioDirectory directory = arg_item->title;
    if (arg_item->title == "/find_result" && m_find_result_typed) directory = m_find_result_typed;
    const auto key = cache_key(directory);
    // Py と同様、折り畳み時にそのフォルダーの内容キャッシュを破棄し、
    // 次の展開で読み直す。 検索結果は折り畳むだけなら内容を保持する。
    if (std::holds_alternative<::cw::lib::String>(directory))
        m_scenario_cache_typed.erase(key);
    m_expanded_tree_paths.erase(key);
    request_dialog_presentation_refresh();
    sync_ui();
}

void ScenarioSelect::OnTreeSelChanged(std::shared_ptr<::cw::lib::Window> arg_event)
{
    // 非表示・処理中のツリーの選択イベントを無視する。共通Presentation
    // が終了済みの場合も入力を受け付けない。
    if (!arg_event || m_processing_typed || m_finished_typed || !is_tree_visible()) return;
    // Window は wx の選択 TreeItem に相当する。id は平坦化し
    // た表示ノードの位置で、title が指定されていればそのノードのパスを表す。
    ScenarioSelectUiState tree_state;
    populate_tree_ui_state(tree_state);
    auto node_index = arg_event->id;
    if (node_index < 0 || static_cast<std::size_t>(node_index) >= tree_state.tree_nodes.size() ||
        (!arg_event->title.empty() && tree_state.tree_nodes[static_cast<std::size_t>(node_index)].path != arg_event->title)) {
        node_index = -1;
        for (std::size_t i = 0; !arg_event->title.empty() && i < tree_state.tree_nodes.size(); ++i) {
            const auto& node = tree_state.tree_nodes[i];
            if (node.path == arg_event->title || lower_ascii(node.label) == lower_ascii(arg_event->title)) {
                node_index = static_cast<::cw::lib::Integer>(i);
                break;
            }
        }
    }
    if (node_index < 0) return;
    m_presentation_state.tree_selected_node_index = node_index;
    _tree_selchanged();
    if (scenario_layout_metrics().paper_and_tree) {
        // これは届いたイベントの処理であり、共通 UI の変更検出ではない。 Py
        // と同様、同じ項目を指すイベントが繰り返されても効果音・再描画を行う。
        if (!m_no_treechangedsound_typed && !m__no_treechangedsound)
            scenario_select_play_sound("page");
        draw(true);
    }
}

void ScenarioSelect::_tree_selchanged()
{
    // 共通入力と同じ親・キャッシュ・絞り込み・dirstack の遷移を再利用する。 Py の
    // OnTreeSelChanged が、このコールバックの後で効果音と張り紙の再描画を行う。
    (void)select_tree_node(m_presentation_state.tree_selected_node_index, false, false);
}

std::vector<std::tuple<::cw::lib::Value, ::cw::lib::String>> ScenarioSelect::get_dirstack(std::shared_ptr<::cw::lib::Window> arg_paritem)
{
    std::vector<std::tuple<::cw::lib::Value, ::cw::lib::String>> result;
    if (!arg_paritem) return result;
    if (arg_paritem->id == -1) {
        // ネイティブのルートは、wx の非表示ルートと同様に合成した要素である。
        return arg_paritem->title == m_scedir_typed ? result
                                                    : std::vector<std::tuple<::cw::lib::Value, ::cw::lib::String>>{};
    }
    if (arg_paritem->id < 0) return result;

    ScenarioSelectUiState state;
    populate_tree_ui_state(state);
    const auto node_index = arg_paritem->id;
    if (static_cast<std::size_t>(node_index) >= state.tree_nodes.size()) return result;
    const auto& selected = state.tree_nodes[static_cast<std::size_t>(node_index)];
    // Window.id は平坦化した表示ノードの位置であり、title もそのノードを指
    // している必要がある。 古い受け渡し情報を、現在の dirstack で代用しない。
    if (selected.path.empty() || selected.path != arg_paritem->title) return result;

    std::vector<::cw::lib::Integer> ancestors;
    for (auto index = node_index; index >= 0;) {
        if (static_cast<std::size_t>(index) >= state.tree_nodes.size()) return {};
        ancestors.push_back(index);
        index = state.tree_nodes[static_cast<std::size_t>(index)].parent_index;
    }
    std::reverse(ancestors.begin(), ancestors.end());
    result.reserve(ancestors.size());
    for (const auto index : ancestors) {
        const auto& ancestor = state.tree_nodes[static_cast<std::size_t>(index)];
        if (ancestor.icon_index == 5) {
            result.emplace_back(::cw::lib::Value(m_scedir_typed), "/find_result");
            continue;
        }
        if (ancestor.path.empty()) return {};
        auto parent = path_text(std::filesystem::u8path(ancestor.path).parent_path());
        if (parent.empty()) parent = m_scedir_typed;
        result.emplace_back(::cw::lib::Value(std::move(parent)), basename_of(ancestor.path));
    }
    return result;
}

void ScenarioSelect::select_treeitem(::cw::lib::Integer arg_index)
{
    select_index(arg_index);
}

void ScenarioSelect::updated_names(::cw::lib::String arg_dpath, std::vector<std::tuple<::cw::lib::Value, ::cw::lib::String>> arg_dirstack, ::cw::lib::String arg_startdir, std::set<::cw::lib::String> arg_expandedset)
{
    (void)arg_dirstack; (void)arg_startdir; (void)arg_expandedset;
    request_dialog_presentation_refresh();
    if (!is_tree_visible() || m_finished_typed || m__quit || arg_dpath.empty()) return;
    const auto key=cache_key(ScenarioDirectory(arg_dpath));
    if (m_expanded_tree_paths.contains(key) && !m_scenario_cache_typed.contains(key))
        (void)directory_candidates(ScenarioDirectory(arg_dpath),true);
    sync_ui();
}

std::vector<::cw::lib::Value> ScenarioSelect::_narrow_scenario(std::vector<::cw::lib::Value> arg_headers)
{
    std::vector<ScenarioCandidate> candidates;
    for (const auto& value : arg_headers) {
        if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&value.storage()); object && *object) {
            if (auto header = std::dynamic_pointer_cast<::cw::header::ScenarioHeader>(*object)) candidates.emplace_back(header);
            else if (auto result = std::dynamic_pointer_cast<FindResult>(*object)) candidates.emplace_back(result);
        } else if (const auto path = value_string(value); !path.empty()) candidates.emplace_back(path);
    }
    std::vector<ScenarioCandidate> directories;
    std::vector<std::shared_ptr<::cw::header::ScenarioHeader>> headers;
    for (const auto& candidate : candidates) {
        if (!candidate_is_showing(candidate)) continue;
        if (const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&candidate); header && *header)
            headers.push_back(*header);
        else
            directories.push_back(candidate);
    }
    headers = _sort_headers(std::move(headers));
    std::vector<::cw::lib::Value> result;
    for (const auto& candidate : directories) result.push_back(candidate_to_value(candidate));
    for (const auto& header : headers) result.push_back(candidate_to_value(ScenarioCandidate(header)));
    return result;
}

bool ScenarioSelect::_update_narrowparams()
{
    const auto params = _get_narrowparams();
    std::ostringstream signature;
    signature << std::get<1>(params) << '|'
              << (std::get<2>(params).has_value() ? std::to_string(*std::get<2>(params)) : std::string("-")) << '|'
              << std::get<3>(params) << '|' << std::get<4>(params) << '|' << std::get<5>(params) << '|'
              << std::get<6>(params) << '|' << std::get<7>(params) << '|'
              << std::get<8>(params);
    for (const auto type : std::get<0>(params)) signature << '|' << type;
    const auto serialized = signature.str();
    if (m_last_narrow_signature_typed == serialized) return false;
    m_last_narrow_signature_typed = serialized;
    m__last_narrowparams = ::cw::lib::Value(static_cast<::cw::lib::Integer>(serialized.size()));
    return true;
}

bool ScenarioSelect::is_showing(std::shared_ptr<::cw::header::ScenarioHeader> arg_header)
{
    return arg_header && candidate_is_showing(ScenarioCandidate(std::move(arg_header)));
}

std::tuple<std::set<::cw::lib::Integer>, ::cw::lib::String, std::optional<::cw::lib::Integer>, bool, ::cw::lib::Integer, bool, bool, bool, ::cw::lib::Integer> ScenarioSelect::_get_narrowparams() const
{
    std::set<::cw::lib::Integer> types;
    if (m_narrow_type_typed == 0) types = {1, 2, 3, 4, 5}; else types.insert(m_narrow_type_typed);
    // CPython 3.8 の Unicode 小文字変換表を使い、新しい文字も Py の UCD 12.1 の動作に合わせる。
    const auto narrow = ::cw::lib::encoding::python_lower(m_search_text);
    const bool search_visible = is_showingaddctrl();
    const bool donarrow = search_visible && !narrow.empty();
    std::optional<::cw::lib::Integer> intnarrow;
    if (types.contains(4) && donarrow) intnarrow = ::cw::scenariodb::parse_level_search(narrow);
    auto level=m_show_unfitness_typed ? 0 : m_average_level_typed;
    if (!m_show_unfitness_typed && ::cw::g_cwpy) {
        const auto pcards=::cw::g_cwpy->get_pcards(::cw::lib::Value("unreversed"));
        if (pcards.empty()) throw std::domain_error("Scenario level average requires party members");
        ::cw::lib::Integer total=0;
        for (const auto& card:pcards) total+=card->m_level;
        level=total/static_cast<::cw::lib::Integer>(pcards.size());
    }
    return {types, narrow, intnarrow, donarrow, level, m_show_unfitness_typed, m_show_completed_typed, m_show_invisible_typed, m_sort_type_typed};
}

bool ScenarioSelect::_is_showing(::cw::lib::Value arg_header, std::set<::cw::lib::Integer> arg_ntypes, ::cw::lib::String arg_narrow, std::optional<::cw::lib::Integer> arg_intnarrow, bool arg_donarrow, ::cw::lib::Integer arg_level) const
{
    if (const auto* object = std::get_if<::cw::lib::ObjectPtr>(&arg_header.storage()); object && *object) {
        auto header = std::dynamic_pointer_cast<::cw::header::ScenarioHeader>(*object);
        if (!header) return true;
        const auto level_min = value_integer(header->m_levelmin);
        const auto level_max = value_integer(header->m_levelmax);
        if (!m_show_unfitness_typed && !(arg_donarrow && arg_ntypes.size() == 1 && arg_ntypes.contains(4)) &&
            ((level_min != 0 && arg_level < level_min) || (level_max != 0 && level_max < arg_level))) return false;
        if (!m_show_completed_typed && is_complete(header)) return false;
        if (!m_show_invisible_typed && is_invisible(header)) return false;
        if (!arg_donarrow) return true;
        // 新しいネイティブの Unicode 表ではなく、両側を CPython 3.8/UCD 12.1 に揃える。
        const auto needle = ::cw::lib::encoding::python_lower(arg_narrow);
        const auto contains = [&](const ::cw::lib::String& value) {
            return ::cw::lib::encoding::python_lower(value).find(needle) != ::cw::lib::String::npos;
        };
        if (arg_ntypes.contains(1) && contains(value_string(header->m_name))) return true;
        if (arg_ntypes.contains(2) && contains(value_string(header->m_desc))) return true;
        if (arg_ntypes.contains(3) && contains(value_string(header->m_author))) return true;
        if (arg_ntypes.contains(4) && arg_intnarrow && level_min <= *arg_intnarrow && *arg_intnarrow <= level_max) return true;
        if (arg_ntypes.contains(5) && contains(header->m_fname)) return true;
        return false;
    }
    return true;
}

std::vector<std::shared_ptr<::cw::header::ScenarioHeader>> ScenarioSelect::_sort_headers(std::vector<std::shared_ptr<::cw::header::ScenarioHeader>> arg_seq)
{
    std::stable_sort(arg_seq.begin(), arg_seq.end(), [&](const auto& a, const auto& b) {
        if (!a || !b) return static_cast<bool>(b);
        return scenario_header_less(a, b, m_sort_type_typed);
    });
    return arg_seq;
}

void ScenarioSelect::enable_btn()
{
    if (m_processing_typed) { sync_ui(); return; }
    if (m_candidates_typed.empty()) { m_yesbtn = false; m_infobtn = false; m_nobtn = true; sync_ui(); return; }
    const auto& selected = m_candidates_typed[static_cast<std::size_t>(std::clamp<::cw::lib::Integer>(m_index, 0, static_cast<::cw::lib::Integer>(m_candidates_typed.size()-1)))];
    bool enable = true;
    const bool tree_only = !m_tree.is_none() &&
                           (!::cw::g_cwpy || !::cw::g_cwpy->m_setting || !::cw::g_cwpy->m_setting->m_show_paperandtree);
    if (const auto* header = std::get_if<std::shared_ptr<::cw::header::ScenarioHeader>>(&selected); header && *header) {
        if (!m_debug_mode_typed && (is_playing(*header) || is_complete(*header) || is_invisible(*header))) enable = false;
    } else if (std::holds_alternative<std::shared_ptr<FindResult>>(selected)) {
        if (!m_tree.is_none() || (
            ::cw::g_cwpy && ::cw::g_cwpy->m_setting && ::cw::g_cwpy->m_setting->m_show_paperandtree)) enable = false;
    } else if (tree_only || !candidate_is_directory(selected)) enable = false;
    m_texts = get_texts();
    m_yesbtn = enable; m_infobtn = !m_texts.empty(); m_nobtn = true;
    sync_ui();
}

std::vector<std::shared_ptr<::cw::dialog::text::ReadmeData>> ScenarioSelect::get_texts()
{
    std::vector<std::shared_ptr<::cw::dialog::text::ReadmeData>> result;
    if (m_candidates_typed.empty() || m_index < 0 || static_cast<std::size_t>(m_index) >= m_candidates_typed.size()) return result;
    const auto& candidate = m_candidates_typed[static_cast<std::size_t>(m_index)];
    if (std::holds_alternative<std::shared_ptr<FindResult>>(candidate)) return result;
    const auto path = ::cw::util::get_linktarget(candidate_path(candidate));
    if (path.empty()) return result;
    const bool recursive = is_scenario_candidate(candidate);
    std::error_code ec;
    const auto requested_path = std::filesystem::u8path(path);
    const bool mounted = ::cardwirth::platform::is_mounted_user_path(requested_path);
    const auto fs_path = mounted
        ? ::cardwirth::platform::resolve_mounted_user_path(requested_path).value_or(requested_path)
        : requested_path;
    const auto mounted_status = mounted ? ::cardwirth::platform::stat_mounted_user_path(fs_path)
                                        : std::optional<::cardwirth::platform::StorageStat>{};
    const auto read_text = [](const std::filesystem::path& file) {
        if (::cardwirth::platform::is_mounted_user_path(file)) {
            const auto raw = ::cardwirth::platform::read_mounted_user_file(file);
            if (!raw) throw std::runtime_error("Readme read failed: " + path_text(file));
            ::cw::lib::Bytes bytes;
            bytes.reserve(raw->size());
            for (const auto byte : *raw) bytes.push_back(static_cast<std::uint8_t>(byte));
            return bytes;
        }
        std::ifstream stream(file, std::ios::binary);
        if (!stream) throw std::runtime_error("Readme open failed: " + path_text(file));
        ::cw::lib::Bytes bytes;
        std::array<char, 65536> buffer;
        for (;;) {
            stream.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
            const auto count = stream.gcount();
            bytes.insert(bytes.end(), buffer.data(), buffer.data() + count);
            if (stream.bad() || (stream.fail() && !stream.eof()))
                throw std::runtime_error("Readme read failed: " + path_text(file));
            if (stream.eof()) return bytes;
        }
    };
    if (recursive && (mounted ? mounted_status && mounted_status->is_file()
                              : std::filesystem::is_regular_file(fs_path, ec))) {
        // Py の CAB 展開サブプロセスは、例外なしで失敗する場合がある。 ZIP
        // の読み取り失敗は引き続き伝播させ、CAB から既に抽出したテキストは保持する。
        const bool cabinet=lower_ascii(path_text(fs_path.extension()))==".cab";
        try {
        const auto reader = ::cw::lib::archive::Reader::open(fs_path);
        for (const auto& entry : reader.entries()) {
            if (entry.directory || lower_ascii(path_text(std::filesystem::u8path(entry.name).extension())) != ".txt") continue;
            const auto raw = reader.read(entry);
            ::cw::lib::Bytes bytes;
            bytes.reserve(raw.size());
            for (const auto byte : raw) bytes.push_back(static_cast<std::uint8_t>(byte));
            auto data = std::make_shared<::cw::dialog::text::ReadmeData>();
            data->initialize(path_text(std::filesystem::u8path(entry.name).filename()), std::move(bytes));
            result.push_back(std::move(data));
        }
        } catch (...) { if (!cabinet) throw; }
    } else if (mounted ? mounted_status && mounted_status->is_directory()
                       : std::filesystem::is_directory(fs_path, ec)) {
        if (mounted) {
            std::vector<std::filesystem::path> files;
            const std::function<void(const std::filesystem::path&)> visit = [&](const auto& directory) {
                // Python と同様、os.walk はディレクトリー列挙の失敗を
                // 無視するが、非再帰の os.listdir 分岐では伝播させる。
                const auto entries = ::cardwirth::platform::list_mounted_user_path(directory, !recursive);
                if (!entries) return;
                std::vector<std::filesystem::path> directories;
                for (const auto& entry : *entries) {
                    if (entry.stat.is_directory() && recursive) { directories.push_back(entry.path); continue; }
                    if ((recursive && !entry.stat.is_file()) || lower_ascii(path_text(entry.path.extension())) != ".txt") continue;
                    files.push_back(entry.path);
                }
                for (const auto& child : directories) visit(child);
            };
            visit(fs_path);
            // ALL でも、Python と同じパス収集と読み取りの区切りを維持する。
            for (const auto& file : files) {
                auto data = std::make_shared<::cw::dialog::text::ReadmeData>();
                const auto name = recursive ? file.lexically_relative(fs_path) : file.filename();
                data->initialize(path_text(name), read_text(file));
                result.push_back(std::move(data));
            }
        } else if (recursive) {
            std::vector<std::filesystem::path> files;
            const std::function<void(const std::filesystem::path&)> walk = [&](const auto& directory) {
                std::error_code error;
                std::vector<std::filesystem::directory_entry> entries;
                for (std::filesystem::directory_iterator it(directory,error), end;
                     !error && it!=end; it.increment(error)) entries.push_back(*it);
                // os.walk と同様、読み取れないディレクトリーだけを飛ばし、兄弟は処理する。
                if (error) return;
                std::vector<std::filesystem::path> directories;
                for (const auto& entry : entries) {
                    error.clear();
                    if (entry.is_directory(error)) { directories.push_back(entry.path()); continue; }
                    error.clear();
                    if (lower_ascii(path_text(entry.path().extension()))==".txt" && entry.is_regular_file(error))
                        files.push_back(entry.path());
                }
                for (const auto& child : directories) {
                    error.clear();
                    if (!std::filesystem::is_symlink(child,error) && !error) walk(child);
                }
            };
            walk(fs_path);
            // Python と同様、先にパスを収集する。 上のディレクトリ
            // ー単位の列挙とは異なり、ファイル読み取りの失敗は伝播させる。
            for (const auto& file : files) {
                auto bytes = read_text(file);
                auto data = std::make_shared<::cw::dialog::text::ReadmeData>();
                data->initialize(path_text(file.lexically_relative(fs_path)), std::move(bytes));
                result.push_back(std::move(data));
            }
        } else {
            // これは os.walk ではなく os.listdir の処理である。 列挙や .txt
            // で終わる名前の読み込みは、対象がディレクトリーの場合も含め、失敗を呼び出し側へ伝える。
            for (const auto& entry : std::filesystem::directory_iterator(fs_path)) {
                if (lower_ascii(path_text(entry.path().extension())) != ".txt") continue;
                auto bytes = read_text(entry.path());
                auto data = std::make_shared<::cw::dialog::text::ReadmeData>();
                data->initialize(path_text(entry.path().filename()), std::move(bytes));
                result.push_back(std::move(data));
            }
        }
    }
    return result;
}

void ScenarioSelect::conv_scenario(::cw::lib::String arg_path)
{
    if (std::holds_alternative<std::shared_ptr<FindResult>>(m_nowdir_typed)) {
        scenario_select_play_sound("error");
        return;
    }
    if (arg_path.empty() || !std::filesystem::is_directory(std::filesystem::u8path(arg_path))) {
        scenario_select_play_sound("error");
        if (m_host_services) m_host_services->message("メッセージ", "カードワースのシナリオのディレクトリではありません。");
        return;
    }
    if (!std::filesystem::is_regular_file(std::filesystem::u8path(arg_path) / "Summary.wsm")) {
        scenario_select_play_sound("error");
        if (m_host_services) m_host_services->message("メッセージ", "カードワースのシナリオのディレクトリではありません。");
        return;
    }
    scenario_select_play_sound("click");
    if (m_host_services && !m_host_services->confirm("シナリオ変換", "「" + basename_of(arg_path) + "」を変換します。\nよろしいですか？")) return;

    ::cw::lib::String destination = m_scedir_typed;
    if (const auto* current = std::get_if<::cw::lib::String>(&m_nowdir_typed); current && !current->empty())
        destination = ::cw::util::get_linktarget(*current);
    if (destination.empty()) destination = m_scedir_typed;
    auto temp_root = value_string(::cw::g_tempdir);
    if (temp_root.empty() && ::cw::g_cwpy) temp_root = ::cw::g_cwpy->m_tempdir;
    if (temp_root.empty()) temp_root = path_text(std::filesystem::temp_directory_path());
    const auto temp_destination = path_text(std::filesystem::u8path(temp_root) / "OldScenario");

    auto scenario = std::make_shared<::cw::binary::cwscenario::CWScenario>();
    scenario->initialize(arg_path, temp_destination, current_skintype(), "Material", true);
    if (!scenario->is_convertible()) {
        scenario_select_play_sound("error");
        if (m_host_services)
            m_host_services->message("メッセージ", "CardWirth ver1.20以上対応の\nシナリオしか変換できません。");
        return;
    }
    scenario->load();
    m_processing_typed = true;
    struct ResetProcessing { bool& value; ~ResetProcessing() { value=false; } } reset_processing{m_processing_typed};
    ::cw::lib::String converted;
    ::cw::lib::String archive_path;
    bool conversion_completed = false;
    try {
        auto parent = std::make_shared<::cw::lib::Window>();
        parent->native_handle = m_parent_native_handle;
        auto progress = std::make_shared<::cw::dialog::progress::ProgressDialog>();
        const auto maximum = std::max<::cw::lib::Integer>(2, scenario->m_maxnum + 2);
        progress->initialize(parent, scenario->m_name + "の変換", "", maximum);
        const bool shown = ::cw::dialog::progress::run_modal_task(
            progress, [scenario, destination, &converted, &archive_path, maximum](const auto& update) {
                // Py と同様、変換・アーカイブ作成・一時ディレクトリー
                // 削除を、全ホストで同じ一つの ProgressDialog
                // に表示する。 Py は curnum/message
                // を 1ms ごとに確認する。変換器はワーカースレッド
                // で同じレコード単位の状態を公開し、 update を
                // 通してコピーすることで、同期なしの読み取りを避ける。
                converted = scenario->convert(update);
                if (converted.empty())
                    throw std::runtime_error("scenario conversion produced no output");
                const auto archive_name = basename_of(converted) + ".wsn";
                archive_path = ::cw::util::dupcheck_plus(
                    path_text(std::filesystem::u8path(destination) / archive_name), false, false);
                update(scenario->m_curnum + 1, "シナリオを圧縮しています...");
                ::cw::util::compress_zip(converted, archive_path, true);
                update(scenario->m_curnum + 2, "一時フォルダを削除しています...");
                ::cw::util::remove(converted, false);
            });
        if (!shown) throw std::runtime_error("scenario conversion progress could not be shown");
        const auto show_error_log = [this](const ::cw::lib::String& log) {
            if (log.empty()) return;
            auto parent = std::make_shared<::cw::lib::Window>();
            parent->native_handle = m_parent_native_handle;
            m_error_log_dialog = std::make_shared<::cw::dialog::etc::ErrorLogDialog>();
            m_error_log_dialog->initialize(std::move(parent), log);
            (void)::cw::dialog::show_common_modal_presentation(m_error_log_dialog);
        };
        show_error_log(scenario->m_errorlog);
        scenario_select_play_sound("harvest");
        if (m_host_services) m_host_services->message("メッセージ", "データの変換が完了しました。");
        if (m_db_typed) m_db_typed->insert_scenario(archive_path, true, current_skintype());
        m_nowdir_typed = destination;
        load_directory(m_nowdir_typed, true);
        for (std::size_t i = 0; i < m_candidates_typed.size(); ++i) {
            if (candidate_path(m_candidates_typed[i]) == archive_path) {
                m_index = static_cast<::cw::lib::Integer>(i);
                break;
            }
        }
        _update_saveddirstack();
        scenario_select_play_sound("page");
        conversion_completed = true;
    } catch (...) {
        ::cw::util::print_ex(std::nullopt);
        if (!scenario->m_errorlog.empty()) {
            auto parent = std::make_shared<::cw::lib::Window>();
            parent->native_handle = m_parent_native_handle;
            m_error_log_dialog = std::make_shared<::cw::dialog::etc::ErrorLogDialog>();
            m_error_log_dialog->initialize(std::move(parent), scenario->m_errorlog);
            (void)::cw::dialog::show_common_modal_presentation(m_error_log_dialog);
        }
        scenario_select_play_sound("error");
        if (m_host_services) m_host_services->message("メッセージ", "シナリオの変換に失敗しました。");
    }
    m_processing_typed = false;
    if (conversion_completed) {
        draw(true);
        enable_btn();
    } else {
        sync_ui();
    }
}

void ScenarioSelect::OnOk(std::shared_ptr<::cw::lib::Window> arg_event)
{
    (void)arg_event;
#if defined(CARDWIRTH_LOG_ENABLED)
    log_scenarioselect("OnOk begin list=" + std::to_string(m_list.size()) +
                       " candidates=" + std::to_string(m_candidates_typed.size()) +
                       " index=" + std::to_string(m_index) +
                       " quit=" + (m__quit ? "1" : "0"));
#endif
    if (m_list.empty() || m__quit) return;
    m__quit = true;
    _stop_poster_animation();
    if (!::cw::g_cwpy) return;
    const auto* frame_value = std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_frame.storage());
    if (!frame_value || !*frame_value) return;
    const auto frame = std::dynamic_pointer_cast<::cw::frame::Frame>(*frame_value);
    if (!frame) return;
    const auto dialog = std::dynamic_pointer_cast<ScenarioSelect>(frame->m_active_dialog_model);
    if (dialog) frame->ok_scenarioselect(dialog);
}

void ScenarioSelect::OnCancel2(::cw::lib::Value arg_event)
{
    (void)arg_event;
    if (m__quit) return;
    m__quit = true;
    _stop_poster_animation();
    const auto selected = get_selected();
    m_saved_fullpath_typed = std::get<1>(selected);
    if (::cw::g_cwpy && ::cw::g_cwpy->m_setting) {
        ::cw::g_cwpy->m_setting->m_lastscenario = std::get<0>(selected);
        ::cw::g_cwpy->m_setting->m_lastscenariopath = std::get<1>(selected);
    }
    cancel_selection();
}

void UpdateNamesThread::initialize(std::shared_ptr<::cw::dialog::scenarioselect::ScenarioSelect> arg_dlg, ::cw::lib::String arg_nowdir, ::cw::lib::String arg_dpath, std::vector<std::tuple<::cw::lib::Value, ::cw::lib::String>> arg_dirstack, ::cw::lib::String arg_startdir, std::set<::cw::lib::String> arg_expandedset, ::cw::lib::String arg_skintype)
{
    m_dlg = arg_dlg;
    m_nowdir = std::move(arg_nowdir); m_dpath = std::move(arg_dpath); m_startdir = std::move(arg_startdir); m_skintype = std::move(arg_skintype); m_quit = false;
    m_dirstack_typed=std::move(arg_dirstack);
    m_dirstack = ::cw::lib::Value(static_cast<::cw::lib::Integer>(m_dirstack_typed.size()));
    m_dpaths_typed=::cw::dialog::scenarioinstall::get_dpaths(value_string(m_dpath));
    m_dpaths = ::cw::lib::Value(static_cast<::cw::lib::Integer>(m_dpaths_typed.size()));
    m_expandedset_typed=std::move(arg_expandedset);
    m_expandedset = ::cw::lib::Value(static_cast<::cw::lib::Integer>(m_expandedset_typed.size()));
}

void UpdateNamesThread::run()
{
    _start();
}

void UpdateNamesThread::_start()
{
    // Py と同様、ディレクトリーのデータベース走査を直列に行ってから、二つの UI コールバックを公開する。
    static std::mutex scan_mutex;
    std::scoped_lock scan_lock(scan_mutex);
    if (m_quit) return;
    const auto dialog=m_dlg.lock();
    if (!dialog || !dialog->m_db_typed) return;
    const auto path=value_string(m_dpath), skin=value_string(m_skintype);
    dialog->m_db_typed->update(path,skin,true,true);
    if (m_quit) return;
    const auto headers=dialog->m_db_typed->search_dpath(path,false,skin,false);
    if (m_quit) return;
    std::vector<::cw::lib::Value> names;
    std::vector<ScenarioCandidate> candidates;
    for (const auto& path:m_dpaths_typed) {
        auto name=basename_of(path);
        if (name.size()>=4 && ScenarioSelect::lower_ascii(name.substr(name.size()-4))==".lnk") name.resize(name.size()-4);
        names.emplace_back("["+name+"]");candidates.emplace_back(path);
    }
    for (const auto& header:headers) { names.push_back(dialog->candidate_to_value(ScenarioCandidate(header)));candidates.emplace_back(header); }
    const auto frame=::cw::g_cwpy ? std::dynamic_pointer_cast<::cw::frame::Frame>(
        std::get_if<::cw::lib::ObjectPtr>(&::cw::g_cwpy->m_frame.storage()) ?
        std::get<::cw::lib::ObjectPtr>(::cw::g_cwpy->m_frame.storage()) : nullptr) : nullptr;
    if (!frame) throw std::logic_error("Directory result requires UI dispatcher");
    const auto owner=weak_from_this().lock();
    const std::weak_ptr<int> lifetime=m_callback_lifetime;
    const auto nowdir=value_string(m_nowdir), startdir=value_string(m_startdir);
    const auto stack=m_dirstack_typed;const auto expanded=m_expandedset_typed;
    frame->exec_func([this,owner,lifetime,dialog,frame,names=std::move(names),candidates=std::move(candidates),path,nowdir,startdir,stack,expanded](const auto&,const auto&) mutable -> ::cw::lib::Value {
        if (lifetime.expired()) return {};
        // Py と同様、走査後に届いたキャンセルを確認する前に名前を公開する。
        const auto current=std::get_if<::cw::lib::String>(&dialog->m_nowdir_typed);
        if (current && *current==nowdir) { dialog->m_names=std::move(names);dialog->m_names_typed=candidates; }
        if (m_quit) return {};
        const auto key=dialog->cache_key(ScenarioDirectory(path));
        if (dialog->m_expanded_tree_paths.contains(key)) dialog->m_scenario_cache_typed[key]=std::move(candidates);
        dialog->m_loading_tree_paths.erase(key);
        frame->exec_func([dialog,path,startdir,stack,expanded](const auto&,const auto&) -> ::cw::lib::Value {
            dialog->updated_names(path,stack,startdir,expanded);return {};
        });
        if (dialog->m_updatenames_thr && dialog->m_updatenames_thr->get()==this) dialog->m_updatenames_thr.reset();
        return {};
    });
}

